window.__DIGESTO_NOVEDADES={"v": 1, "generado": "2026-11-07T13:19", "sibom": {"ultimo_boletin": "120º de San Andrés de Giles · 21/10/2026", "consulta": {"fecha": "2026-11-07T12:45", "ok": true}}, "hcd": {"consulta": {"fecha": "2026-11-07T13:19", "ok": true}}, "list": [{"id": "ord-2847-2026", "t": "ord", "n": 2847, "y": 2026, "a": "Adhesión a la Resolución que establece el Régimen para la elaboración de chacinados", "texto": "ORDENANZA N° 2847\nVISTO:\nLa Resolución Nº 350/2025 del Ministerio de Desarrollo Agrario de la Provincia de Buenos Aires, mediante la cual se crea el régimen para la elaboración de chacinados y salazones de pequeña escala (Charcutería), destinado a promover la producción artesanal con adecuados estándares de inocuidad alimentaria; y\nCONSIDERANDO:\nQue la producción artesanal de chacinados y salazones constituye una actividad de importancia económica, cultural y productiva para numerosos emprendimientos familiares y pequeños productores del Partido de San Andrés de Giles, contribuyendo al agregado de valor de la producción primaria y al fortalecimiento de las economías regionales.\nQue la Ley Provincial Nº 11.123 Ley Sanitaria de Carnes de la Provincia de Buenos Aires regula la habilitación y funcionamiento de los establecimientos donde se faenan animales, se elaboran, procesan, depositan o transportan productos, subproductos y derivados de origen animal, estableciendo las condiciones higiénico-sanitarias y de seguridad alimentaria que deben cumplir dichas actividades.\nQue, en el marco de dicha ley, el Ministerio de Desarrollo Agrario de la Provincia de Buenos Aires dictó la Resolución Nº 350/2025, ampliando su marco normativo mediante la incorporación de condiciones edilicias, higiénico-sanitarias y requisitos documentales específicos para la habilitación de fábricas de chacinados y/o salazones de pequeña escala, favoreciendo la formalización de los productores artesanales sin desatender las garantías de inocuidad alimentaria.\nQue la adhesión del Municipio al régimen establecido por la Resolución Nº 350/2025 permitirá acompañar a los productores locales en su proceso de regularización, facilitando el acceso a un régimen de habilitación adaptado a las características de la producción artesanal, promoviendo el desarrollo local, la generación de empleo y la seguridad alimentaria.\nQue la normativa provincial tiene por finalidad facilitar la formalización de estos establecimientos, promoviendo su desarrollo sin descuidar las condiciones higiénico-sanitarias necesarias para proteger la salud pública.\nQue la adhesión municipal permitirá articular acciones con el Ministerio de Desarrollo Agrario, favoreciendo la capacitación, asistencia técnica, habilitación y fiscalización de los establecimientos comprendidos en dicho régimen.\nQue resulta conveniente fomentar el agregado de valor en origen, la generación de empleo local y el fortalecimiento de las economías regionales, promoviendo productos elaborados bajo condiciones de calidad e inocuidad.\nPor ello, el Honorable Concejo Deliberante, en uso de las facultades que les son propias sanciona la siguiente:\nORDENANZA\nArtículo 1°: Adhiérase el Municipio de San Andrés de Giles a la Resolución Nº 350/2025 del Ministerio de Desarrollo Agrario de la Provincia de Buenos Aires, que amplía el marco normativo de la Ley Provincial de Carnes N° 11.123/91, mediante la cual se establece el régimen para la elaboración de chacinados y salazones de pequeña escala (Charcutería)\nArtículo 2°: Designase como Autoridad de Aplicación de la presente Ordenanza al Departamento Ejecutivo, a través del área que determine, con intervención de la Dirección de Bromatología y demás dependencias competentes.\nArtículo 3°: El Departamento Ejecutivo promoverá la inscripción y regularización de los establecimientos alcanzados por la normativa provincial, brindando asesoramiento a los productores locales para facilitar su incorporación al régimen.\nArtículo 4°: Las habilitaciones y controles bromatológicos que correspondan se efectuarán conforme a la normativa provincial vigente, al Código Alimentario Argentino, a la legislación sanitaria aplicable y a las ordenanzas municipales en la materia.\nArtículo 5°: Invítese a las instituciones rurales, cooperativas, asociaciones de productores, establecimientos educativos con orientación agropecuaria y demás entidades vinculadas al sector a participar de las acciones de promoción y capacitación que se desarrollen en el marco de la presente Ordenanza.\nArtículo 6°: Autorizase al Departamento Ejecutivo a dictar las normas reglamentarias y complementarias necesarias para la implementación de la presente Ordenanza.\nArtículo 7°: Remítase copia de la presente al organismo de la Provincia de Buenos Aires que corresponda.\nArtículo 8°: De forma.-\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 29 de Octubre de 2026.-", "archivo": "2026-Ord02847 (Adhesión a la Resolución que establece el Régimen para la elaboración de chacinados).docx", "rz": "X", "c": "Adhesiones a leyes nacionales y provinciales", "v": "Sancionada (en plazo de promulgación)", "fe": "29 de octubre de 2026", "se": "Sesión Ordinaria", "vi": "La Resolución Nº 350/2025 del Ministerio de Desarrollo Agrario de la Provincia de Buenos Aires, mediante la cual se crea el régimen para la elaboración de chacinados y salazones de pequeña escala (Charcutería), destinado a promover la producción artesanal con adecuados estándares de inocuidad alimentaria; y", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "Sancionada por el H.C.D. El Departamento Ejecutivo tiene diez días hábiles desde la notificación para promulgarla o vetarla (art. 108 inc. 2 LOM); plazo estimado hasta el 19/11/2026.", "rf": [], "pr": {"estado": "en_plazo", "limite": "2026-11-19", "etiqueta": "En plazo de promulgación"}, "fs": "2026-10-29", "ts": 1, "src": "docx"}, {"id": "ord-2846-2026", "t": "ord", "n": 2846, "y": 2026, "a": "Regulación circulación de vehículos de movilidad personal", "texto": "ORDENANZA N° 2846\nVISTO:\nLa creciente utilización de monopatines eléctricos y demás Vehículos de Movilidad Personal (VMP) como medios de movilidad urbana en el Partido de San Andrés de Giles;\nLa Ley Nacional N° 24.449, de Tránsito y Seguridad Vial, y sus modificatorias;\nLa Ley Nacional N° 26.363, de creación de la Agencia Nacional de Seguridad Vial y la Disposición N° 480/2020 de dicho organismo, mediante la cual se aprobó el “Marco Regulatorio para la Circulación de Vehículos de Movilidad Personal”;\nLa Ley Provincial N° 13.927, por la cual la Provincia de Buenos Aires adhiere a las Leyes Nacionales N° 24.449 y N° 26.363 y a sus normas reglamentarias; y,\nCONSIDERANDO:\nQue, los Vehículos de Movilidad Personal constituyen una modalidad de transporte cuya utilización se ha incrementado en los últimos años, particularmente para desplazamientos urbanos de corta distancia;\nQue, los monopatines eléctricos presentan características que los convierten en una alternativa de movilidad ágil, económica y de bajo impacto ambiental, pudiendo contribuir al desarrollo de una movilidad urbana más sustentable;\nQue, la incorporación de nuevas modalidades de movilidad requiere el establecimiento de reglas claras que garanticen una convivencia segura entre sus usuarios, los peatones, los ciclistas, los motociclistas y los demás conductores;\nQue, la Agencia Nacional de Seguridad Vial, mediante la Disposición N° 480/2020, estableció un marco regulatorio específico para la circulación de Vehículos de Movilidad Personal, fijando condiciones de seguridad y circulación;\nQue, dicho marco contempla, entre otros aspectos, condiciones relativas a la velocidad máxima de circulación, los sistemas de frenos e iluminación, los dispositivos de alerta sonora, el uso obligatorio de casco protector, la edad mínima de los conductores y las prohibiciones vinculadas a determinadas conductas durante la conducción;\nQue, asimismo, establece restricciones relacionadas con la circulación por aceras y zonas exclusivas para peatones, el transporte de pasajeros y la conducción bajo los efectos del alcohol u otras sustancias que puedan afectar las capacidades psicofísicas del conductor;\nQue, la Provincia de Buenos Aires, mediante la Ley N° 13.927, adhirió a las Leyes Nacionales N° 24.449 y N° 26.363, conformando un marco normativo en materia de tránsito y seguridad vial;\nQue, resulta conveniente establecer, en el ámbito del Partido de San Andrés de Giles, disposiciones específicas que complementen el marco normativo vigente y permitan adecuarlo a las características y necesidades de la movilidad local, dentro de las competencias municipales;\nQue, resulta necesario promover el uso responsable de los Vehículos de Movilidad Personal, estableciendo condiciones de seguridad para sus conductores y para el conjunto de los usuarios de la vía pública;\nQue, corresponde al Honorable Concejo Deliberante, en ejercicio de sus atribuciones, dictar las normas necesarias para ordenar la circulación en el ámbito municipal, promoviendo una movilidad segura, responsable y sustentable;\nPor ello, el Honorable Concejo Deliberante de San Andrés de Giles, en uso de sus atribuciones, sanciona la siguiente:\nORDENANZA\nArtículo 1°: Adhiérase, en el ámbito del Partido de San Andrés de Giles, al «Marco Regulatorio para la Circulación de Vehículos de Movilidad Personal», aprobado por la Disposición N° 480/2020 de la Agencia Nacional de Seguridad Vial, o a la norma que en el futuro la modifique, sustituya o complemente, en cuanto resulte aplicable a la jurisdicción municipal.\nArtículo 2°: A los efectos de la presente Ordenanza, se entiende por Vehículo de Movilidad Personal (VMP) todo vehículo de una o más ruedas, destinado al traslado de personas y autopropulsado mediante motorización eléctrica, con las exclusiones previstas en la normativa nacional vigente.\nQuedan comprendidos, entre otros, los monopatines eléctricos y aquellos dispositivos que reúnan las características establecidas en la definición precedente.\nArtículo 3°: Los Vehículos de Movilidad Personal que circulen en el Partido de San Andrés de Giles deberán reunir las condiciones de seguridad exigidas por la normativa vigente y contar, como mínimo, con los siguientes elementos:\nUn sistema de frenos que permita detener el vehículo de manera eficaz y segura.\nUna luz delantera de color blanco y una luz trasera de color rojo, que deberán permanecer encendidas durante la circulación, conforme a la normativa aplicable.\nUn sistema de alerta sonora, mediante timbre o bocina, que permita advertir la presencia del vehículo a los demás usuarios de la vía pública.\nUn sistema de limitación de velocidad que impida superar los veinticinco (25) kilómetros por hora, de conformidad con la normativa vigente.\nElementos reflectantes que favorezcan la visibilidad del vehículo y de su conductor.\nArtículo 4°: Será obligatorio para toda persona que conduzca un Vehículo de Movilidad Personal utilizar casco protector debidamente certificado, de acuerdo con las normas de seguridad vigentes.\nArtículo 5°: Los Vehículos de Movilidad Personal podrán ser conducidos únicamente por personas de dieciséis (16) años de edad o mayores, sin perjuicio de las condiciones adicionales que establezca la normativa nacional o provincial vigente.\nArtículo 6°: Prohíbese la circulación de Vehículos de Movilidad Personal por los siguientes sectores:\nVeredas, aceras y demás espacios destinados exclusivamente a la circulación peatonal.\nRutas.\nAutopistas.\nSemiautopistas.\nTodo otro sector cuya circulación se encuentre expresamente prohibida por la autoridad competente, por razones debidamente fundadas de seguridad vial, accesibilidad o protección de los peatones.\nArtículo 7°: Prohíbese a los conductores de Vehículos de Movilidad Personal:\nTransportar acompañantes o pasajeros.\nTransportar animales.\nUtilizar teléfonos celulares, auriculares u otros dispositivos de comunicación, imagen o sonido que puedan distraer su atención durante la conducción.\nCircular bajo los efectos del alcohol, estupefacientes, psicotrópicos, estimulantes u otras sustancias que disminuyan las capacidades psicofísicas necesarias para una conducción segura.\nArtículo 8°: Los conductores de Vehículos de Movilidad Personal deberán respetar las normas de tránsito aplicables, incluidas las señales de tránsito, los semáforos, las prioridades de paso y las demás disposiciones vigentes.\nArtículo 9°: Los Vehículos de Movilidad Personal deberán estacionarse en los espacios habilitados y señalizados para tal fin. En ausencia de espacios específicos, podrán utilizarse los sectores destinados al estacionamiento de ciclomotores y motocicletas, siempre que ello no se encuentre prohibido por la normativa vigente ni obstaculice la circulación peatonal, el acceso a edificios o la utilización de rampas y espacios destinados a personas con discapacidad.\nArtículo 10°: La Autoridad de Aplicación podrá establecer, mediante la reglamentación correspondiente y dentro de sus competencias, calles, avenidas, sectores o corredores específicos para la circulación de Vehículos de Movilidad Personal.\nAsimismo, podrá establecer restricciones de circulación en determinados sectores cuando existan razones debidamente fundadas de seguridad vial, accesibilidad o protección de los peatones, respetando la normativa nacional y provincial vigente.\nArtículo 11°: La Autoridad de Aplicación deberá evaluar y, cuando corresponda conforme a la normativa vigente, exigir la contratación de un seguro de responsabilidad\ncivil para los Vehículos de Movilidad Personal que circulen en el Partido de San Andrés de Giles, de acuerdo con las condiciones y los alcances establecidos por la normativa nacional y provincial aplicable.\nArtículo 12°: Será Autoridad de Aplicación de la presente Ordenanza el Departamento Ejecutivo Municipal, a través del área que determine, al que le corresponderá implementar, fiscalizar y reglamentar sus disposiciones, sin perjuicio de las competencias que correspondan a las autoridades provinciales y nacionales.\nArtículo 13°: El incumplimiento de las disposiciones establecidas en la presente Ordenanza será sancionado de conformidad con el régimen de faltas y contravenciones vigente en el Partido de San Andrés de Giles y con las normas provinciales y nacionales aplicables, según corresponda.\nCuando la normativa vigente lo autorice, la autoridad competente podrá disponer la retención preventiva del vehículo, con sujeción a las condiciones, los procedimientos y las garantías establecidos por la legislación aplicable.\nArtículo 14°: La Autoridad de Aplicación deberá promover y coordinar acciones de fiscalización, concientización y educación vial con los organismos provinciales competentes y con la Agencia Nacional de Seguridad Vial, cuando corresponda.\nArtículo 15°: De forma.-\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 29 de Octubre de 2026.-", "archivo": "2026-Ord02846 (Regulación circulación de vehículos de movilidad personal).docx", "rz": "VIII", "c": "Tránsito, seguridad vial y estacionamiento", "v": "Sancionada (en plazo de promulgación)", "fe": "29 de octubre de 2026", "se": "Sesión Ordinaria", "vi": "La creciente utilización de monopatines eléctricos y demás Vehículos de Movilidad Personal (VMP) como medios de movilidad urbana en el Partido de San Andrés de Giles; La Ley Nacional N° 24.449, de Tránsito y Seguridad Vial, y sus modificatorias; La Ley Nacional N° 26.363, de creación de la Agencia Nacional de Seguridad Vial y la Disposición N° 480/2020 de dicho organismo, mediante la cual se aprobó el “Marco Regulatorio para la Circulación de Vehículos de Movilidad Personal”; La Ley Provincial N° 13.927, por la cual la Provincia de Buenos Aires adhiere a las Leyes Nacionales N° 24.449 y N° 26.", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "Sancionada por el H.C.D. El Departamento Ejecutivo tiene diez días hábiles desde la notificación para promulgarla o vetarla (art. 108 inc. 2 LOM); plazo estimado hasta el 19/11/2026.", "rf": [], "pr": {"estado": "en_plazo", "limite": "2026-11-19", "etiqueta": "En plazo de promulgación"}, "fs": "2026-10-29", "ts": 1, "src": "docx"}, {"id": "ord-2845-2026", "t": "ord", "n": 2845, "y": 2026, "a": "Subdivisión y loteo Rubén Gallo", "texto": "ORDENANZA N° 2845\nVISTO:\nLo actuado en el expediente N° 4101-11305/21; y\nCONSIDERANDO:\nQue a fs. 43/51 del citado expediente, obra un convenio suscripto oportunamente entre el Sr. Intendente Municipal Sr. Miguel Ángel Gesualdi y el Sr. Ruben Abel Gallo.\nQue dicho convenio fue homologado mediante Ordenanza Nº 2452, sancionada por el Honorable Concejo Deliberante durante la sesión extraordinaria celebrada el día 23 de diciembre de 2021 y promulgada mediante Decreto Nº 3376 de fecha 29 de diciembre de 2021.\nQue, el propietario como compensación del presente convenio realizó la donación de la parcela identificada provisoriamente como PARCELA 3y, con una superficie de 10.000 m2, de acuerdo con el croquis que obra en el Anexo IV que forma parte del convenio.\nQue la Dirección De Planeamiento y Obras Particulares mediante expediente 4101-22473/25, solicita la escrituración del inmueble identificado con la siguiente nomenclatura catastral, Circunscripción: II Parcela 36 AR , sita en la ciudad de San Andrés de Giles, Partido del mismo, oportunamente cedida a este municipio por el Sr. Gallo Rubén Abel.\nQue mediante decreto 0717/25 se autoriza la intervención de la Escribanía General de Gobierno de la Provincia de Buenos Aires a fin de proceder a la escrituración conforme lo establece la ley 10.830, de dicho inmueble.\nQue, con fecha 18 de marzo del año 2025, el expediente fue remitido a la Escribanía General de Gobierno, a los fines de su escrituración a nombre del Municipio.\nCon fecha 6 de abril del año 2026, fue devuelto el expediente a la Municipalidad, a fin de realizar una modificación, con respecto a la denominación de la parcela objeto de la operatoria.\nQue, a fin de cumplimentar lo requerido, mediante decreto nº 1069/26, se realizaron las aclaraciones pertinentes, estableciéndose que oportunamente se identificó PROVISORIAMENTE a la parcela a donar a la Municipalidad como “3y” debido al hecho que hasta ese entonces todavía no se encontraba realizada la mensura definitiva de la parcela madre.\nQue, una vez realizada la correspondiente mensura, se establecieron las numeraciones definitivas de las parcelas. De ello se desprende, que la parcela identificada primigeniamente en forma provisoria como 3y, paso a designarse como Pc. 36 AR, también con una superficie de 10.000 m2.\nQue con fecha 11.09.26, la Escribanía General de Gobierno devuelve nuevamente las actuaciones, solicitando que la identificación del inmueble coincida en toda la documentación agregada, incluso en el acuerdo de partes con lo que surge del plano y lo aprobado por ordenanza y decreto municipal.\nQue, en el contexto de dichas actuaciones, a efectos de dar continuidad a la escrituración reseñada, resulta necesario que la identificación del inmueble coincida en toda la documentación obrante en las precitadas actuaciones, incluido en el acuerdo de partes, en la Ordenanza homologatoria del mismo y su decreto promulgatorio, por lo cual se suscribe una adenda, con fecha 06.10.26 entre la Municipalidad y el Sr. Gallo Rubén Abel, a esos efectos.\nQue, al respecto se expidió la Asesoría Letrada Municipal, no formulando objeciones.\nQue, en consecuencia, deberá homologarse por parte de este Órgano Deliberativo, la adenda suscripta.\nPor ello, el HCD en uso de las atribuciones que le son propias, sanciona la siguiente:\nO R D E N A N Z A\nARTICULO 1º: Homologar la adenda suscripta con fecha 06 de octubre del año en curso, entre el Sr. Intendente Municipal y el Sr. Gallo Rubén Abel, que como Anexo I forma parte integrante de la presente ordenanza.\nARTICULO 2º: Ratificar la homologación del convenio autorizado por ordenanza Nº 2452/21, con el agregado de la adenda referenciada en el artículo precedente.\nARTICULO 3º: Autorizar la intervención de la Escribanía General de Gobierno de la Provincia de Buenos Aires a fin de proceder a la escrituración conforme lo establece la ley 10.830, del inmueble identificado con la siguiente nomenclatura catastral: Circunscripción II, Parcela 36 AR, sita en la ciudad de San Andrés de Giles, Partido del mismo nombre.\nARTICULO 4º: Aprobar todas las tramitaciones realizadas y autorizar a realizar y/o suscribir cualquier otra documentación pertinente, con relación al acuerdo objeto de la presente Ordenanza.\nARTICULO 5°: Registrar. Comunicar a las áreas pertinentes en virtud de la naturaleza de la presente norma, comunicar y archivar.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 29 de Octubre de 2026.-", "archivo": "2026-Ord02845 (Subdivisión y loteo Rubén Gallo).docx", "rz": "III", "c": "Fraccionamientos, subdivisiones y apertura de calles", "v": "Sancionada (en plazo de promulgación)", "fe": "29 de octubre de 2026", "se": "Sesión Ordinaria", "vi": "Lo actuado en el expediente N° 4101-11305/21; y", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "Sancionada por el H.C.D. El Departamento Ejecutivo tiene diez días hábiles desde la notificación para promulgarla o vetarla (art. 108 inc. 2 LOM); plazo estimado hasta el 19/11/2026.", "rf": [["Ord", 2452, "Modifica", 1]], "pr": {"estado": "en_plazo", "limite": "2026-11-19", "etiqueta": "En plazo de promulgación"}, "fs": "2026-10-29", "ts": 1, "src": "docx"}, {"id": "ord-2844-2026", "t": "ord", "n": 2844, "y": 2026, "a": "Imponer el nombre Plaza de las Artes a un espacio público", "texto": "ORDENANZA N° 2844\nVISTO:\nLa necesidad de fortalecer y poner en valor los espacios públicos de la ciudad de San Andrés de Giles; la existencia de la plaza ubicada entre las calles Alsina, Avellaneda, Larrañaga y Padre Kaufman, actualmente carente de una denominación oficial; la iniciativa elaborada por los estudiantes de la Escuela de Educación Secundaria Nº 8, cuya orientación es Arte y Música, tendiente a denominar dicho espacio como “Plaza de las Artes”; y\nLo establecido por el Decreto-Ley 6769/58, Ley Orgánica de las Municipalidades de la Provincia de Buenos Aires, en particular sus artículos 24, 25 y 27; y la Ordenanza Municipal N.º 1211, texto ordenado por Decreto N.º 3025/24, relativa a la imposición de nombres a calles y espacios públicos del Partido de San Andrés de Giles; y\nCONSIDERANDO:\nQue corresponde al Honorable Concejo Deliberante, en el marco de sus atribuciones, intervenir en la reglamentación, conservación y puesta en valor de plazas y paseos públicos, así como en la imposición de nombres a calles y sitios públicos;\nQue la plaza ubicada entre las calles Alsina, Avellaneda, Larrañaga y Padre Kaufman constituye un espacio público destinado al encuentro, la recreación, el esparcimiento y la convivencia de los vecinos de la ciudad de San Andrés de Giles;\nQue los espacios públicos cumplen una función social, cultural y educativa que trasciende su utilización como lugares de tránsito o recreación, constituyéndose en ámbitos de encuentro comunitario y construcción de identidad local;\nQue resulta conveniente dotar a dicho espacio de una denominación que contribuya a fortalecer su identidad y que, al mismo tiempo, exprese un valor cultural significativo para la comunidad;\nQue los estudiantes de la Escuela de Educación Secundaria Nº 8, cuya orientación educativa se vincula específicamente con el campo de Arte y Música, han elaborado la propuesta de denominar al espacio “Plaza de las Artes”;\nQue la propuesta constituye una forma concreta de participación estudiantil y ciudadana en los asuntos de interés comunitario, favoreciendo la apropiación del espacio público por parte de las nuevas generaciones;\nQue la música constituye una expresión artística de profundo valor cultural, educativo y social, capaz de promover el encuentro, la participación, la expresión y la construcción de vínculos comunitarios;\nQue la denominación “Plaza de las Artes” resulta adecuada para identificar un espacio público destinado al encuentro y la recreación, y permite vincular simbólicamente el lugar con las prácticas culturales y artísticas desarrolladas en la comunidad;\nQue, asimismo, resulta necesario acompañar la imposición del nombre con acciones destinadas a mejorar las condiciones de uso, seguridad, accesibilidad y disfrute de la plaza por parte de niños, adolescentes, adultos y personas mayores;\nQue, en tal sentido, resulta pertinente prever la incorporación y/o renovación de bancos y mesas, juegos infantiles inclusivos y accesibles, un sector destinado a actividades deportivas y recreativas, arbolado, recipientes para residuos e iluminación adecuada;\nQue el mejoramiento integral del espacio contribuirá a favorecer la convivencia comunitaria, el desarrollo de actividades recreativas, culturales y deportivas y la apropiación responsable del espacio público;\nQue toda intervención deberá contemplar criterios de accesibilidad, seguridad, inclusión, preservación ambiental y adecuada integración con el entorno urbano;\nQue la Ordenanza Nº 1211 establece el procedimiento para la imposición de nombres a espacios públicos del Partido de San Andrés de Giles y contempla entre sus criterios aquellas denominaciones vinculadas con el desarrollo cultural y educativo;\nQue la iniciativa presentada por los estudiantes de la Escuela de Educación Secundaria Nº 8 constituye una oportunidad para articular las instituciones educativas con el gobierno municipal y promover mecanismos concretos de participación de las juventudes en la construcción del espacio público;\nQue corresponde al Departamento Ejecutivo, a través de las áreas municipales competentes, evaluar las características técnicas de las intervenciones propuestas, establecer las prioridades de ejecución y determinar los recursos necesarios, de acuerdo con la disponibilidad presupuestaria y la normativa vigente;\nPor ello, el Honorable Concejo Deliberante de San Andrés de Giles, en uso de las atribuciones que le son propias, sanciona la siguiente\nORDENANZA\nARTÍCULO 1º: Denomínese “PLAZA DE LAS ARTES” al espacio público ubicado entre las calles Alsina, Avellaneda, Larrañaga y Padre Kaufman, de la ciudad cabecera del Partido de San Andrés de Giles.\nARTÍCULO 2º: Encomiéndese al Departamento Ejecutivo Municipal, a través de las áreas competentes, la elaboración y ejecución de un proyecto integral de puesta en valor y mejoramiento de la Plaza de las Artes, procurando adecuar las intervenciones a las características del espacio y a las necesidades de la comunidad.\nARTÍCULO 3º: El proyecto integral de mejoramiento deberá contemplar, de acuerdo con las características técnicas y espaciales del lugar, la incorporación, renovación y/o adecuación de:\na) Bancos y mesas destinados al descanso, encuentro y permanencia de los usuarios.\nb) Sectores destinados a juegos infantiles inclusivos y accesibles.\nc) Espacios destinados a actividades deportivas y recreativas.\nd) Arbolado y vegetación, priorizando especies apropiadas para el espacio urbano y procurando mejorar las condiciones ambientales, de sombra y confort del lugar.\ne) Recipientes para residuos, distribuidos estratégicamente y adecuados para favorecer la limpieza y el cuidado del espacio público.\nf) Iluminación suficiente y eficiente, destinada a mejorar las condiciones de seguridad, circulación y utilización del espacio durante las horas nocturnas.\ng) Las obras y adecuaciones necesarias para garantizar la accesibilidad y circulación segura de personas con discapacidad o movilidad reducida.\nARTÍCULO 4º: Encomiéndese al Departamento Ejecutivo Municipal, a través de las áreas competentes, la incorporación de juegos infantiles inclusivos y equipamiento deportivo y recreativo en la denominada “Plaza de las Artes”, promoviendo la actividad física, el esparcimiento y la integración comunitaria, garantizando condiciones de seguridad, accesibilidad y mantenimiento.\nARTÍCULO 5º: El Departamento Ejecutivo procurará que el proyecto de puesta en valor contemple la posibilidad de incorporar elementos, intervenciones o recursos vinculados con la música y las expresiones artísticas, de manera compatible con las características del espacio y con las condiciones de seguridad, mantenimiento y preservación del patrimonio urbano.\nARTÍCULO 6º: Facúltese al Departamento Ejecutivo a determinar las etapas de ejecución de las obras previstas en la presente Ordenanza, priorizando aquellas intervenciones que resulten necesarias para garantizar condiciones adecuadas de seguridad, accesibilidad, higiene, iluminación y recreación.\nARTÍCULO 7º: La ejecución de las obras previstas en la presente Ordenanza quedará sujeta a la disponibilidad presupuestaria y a las normas vigentes en materia de administración financiera, contrataciones y ejecución del gasto público municipal. En caso de resultar necesario, deberán realizarse las adecuaciones presupuestarias correspondientes, con intervención previa de las áreas municipales competentes.\nARTÍCULO 8º: Encomiéndese al Departamento Ejecutivo la colocación de carteleria identificativa con la denominación oficial “Plaza de las Artes”, procurando que la misma resulte visible, accesible y acorde con las características urbanísticas y paisajísticas del espacio.\nARTÍCULO 9º: Invitase a la Escuela de Educación Secundaria Nº 8 y a sus estudiantes a participar, en carácter consultivo y de acuerdo con las posibilidades que establezca el\nDepartamento Ejecutivo, en las instancias de diseño, definición de criterios estéticos y/o actividades culturales vinculadas con la puesta en valor de la plaza.\nARTÍCULO 10º: El Departamento Ejecutivo dará intervención a las áreas municipales que correspondan, en virtud de la naturaleza de las acciones previstas en la presente Ordenanza, y comunicará al Honorable Concejo Deliberante las etapas de planificación y ejecución del proyecto.\nARTÍCULO 11º: Regístrese, comuníquese al Departamento Ejecutivo, publíquese, dése intervención a las áreas municipales correspondientes y, cumplido, archívese.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 29 de Octubre de 2026.-", "archivo": "2026-Ord02844 (Imponer el nombre Plaza de las Artes a un espacio público).docx", "rz": "XI", "c": "Denominación de plazas, edificios y espacios", "v": "Sancionada (en plazo de promulgación)", "fe": "29 de octubre de 2026", "se": "Sesión Ordinaria", "vi": "La necesidad de fortalecer y poner en valor los espacios públicos de la ciudad de San Andrés de Giles; la existencia de la plaza ubicada entre las calles Alsina, Avellaneda, Larrañaga y Padre Kaufman, actualmente carente de una denominación oficial; la iniciativa elaborada por los estudiantes de la Escuela de Educación Secundaria Nº 8, cuya orientación es Arte y Música, tendiente a denominar dicho espacio como “Plaza de las Artes”; y Lo establecido por el Decreto-Ley 6769/58, Ley Orgánica de las Municipalidades de la Provincia de Buenos Aires, en particular sus artículos 24, 25 y 27; y la Orde", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "Sancionada por el H.C.D. El Departamento Ejecutivo tiene diez días hábiles desde la notificación para promulgarla o vetarla (art. 108 inc. 2 LOM); plazo estimado hasta el 19/11/2026.", "rf": [["Ord", 1211, "Refiere a", 1]], "pr": {"estado": "en_plazo", "limite": "2026-11-19", "etiqueta": "En plazo de promulgación"}, "fs": "2026-10-29", "ts": 1, "src": "docx"}, {"id": "ord-2843-2026", "t": "ord", "n": 2843, "y": 2026, "a": "Imposición del nombre Carlos Gariboto a una calle del Barrio San Bernardo", "texto": "ORDENANZA N° 2843\nVISTO\nEl legado cultural que nos dejó a San Andrés de Giles el recordado Carlos Andrés Garibotto, y\nCONSIDERANDO\nQue la Ley Orgánica de las Municipalidades le confiere al Honorable Concejo Deliberante en su artículo 27 inciso 4) la facultad de “la imposición de nombres a las calles y los sitios públicos”;\nQue debe tenerse en cuenta que las denominaciones comúnmente surgen de nombres y valores universales y nacionales, por lo que con el fin de consolidar identidad y pertenencia será favorable enriquecerlas con aquellos que pertenezcan a la propia comunidad geográfica y humana y resulten propicios para construir memoria, visibilizar y valorar lo cercano;\nQue por lo expuesto ut supra Carlos Andrés Gariboto, cariñosamente conocido como Carlitos, nació en San Andrés de Giles el 30 de noviembre de 1925, un día cargado de significado para la comunidad al celebrarse las fiestas patronales;\nQue, durante su vida, Carlitos se dedicó con pasión a la música y al tango, logrando consolidarse como un referente cultural y dejando un legado imborrable en su pueblo y en la región;\nQue a lo largo de su trayectoria demostró un inquebrantable compromiso con la difusión del repertorio de Carlos Gardel, su máximo ídolo. Esta fue su meta desde joven, la que lo llevó por muchos escenarios locales, regionales, recorriendo diversas ciudades de la provincia de Buenos Aires, traspasando fronteras a países limítrofes como Uruguay y Paraguay donde transmitió la esencia del tango con sencillez y profesionalismo;\nQue su aporte a la música puede ser valorado tanto desde su calidad artística como desde la alegría brindada a través de sus múltiples actuaciones;\nQue en su inclaudicable perseverancia a través de los años se convirtió en acérrimo gardeliano defensor de nuestras costumbres y tradiciones;\nQue por todo lo antes descriptos fue por decreto 237/04 reconocido por su trayectoria artística y por su ejemplar dedicación a la interpretación en guitarra y canto de la música popular argentina;\nPor ello, en uso de las atribuciones que le son propias, el Honorable Concejo Deliberante de San Andrés de Giles, sanciona el siguiente:\nORDENANZA\nArtículo 1º: Establecer la denominación de Carlos Garibotto a la calle N° 37 del Barrio San Bernardo de San Andrés de Giles.\nArtículo 2º: Solicítese al Departamento Ejecutivo que arbitre los medios necesarios para la demarcación y señalización de la calle, mencionada en el artículo 1°.\nArtículo 3º: De forma.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 29 de Octubre de 2026.-", "archivo": "2026-Ord02843 (Imposición del nombre Carlos Gariboto a una calle del Barrio San Bernardo).docx", "rz": "XI", "c": "Imposición de nombres a calles y caminos", "v": "Sancionada (en plazo de promulgación)", "fe": "29 de octubre de 2026", "se": "Sesión Ordinaria", "vi": "El legado cultural que nos dejó a San Andrés de Giles el recordado Carlos Andrés Garibotto, y", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "Sancionada por el H.C.D. El Departamento Ejecutivo tiene diez días hábiles desde la notificación para promulgarla o vetarla (art. 108 inc. 2 LOM); plazo estimado hasta el 19/11/2026.", "rf": [], "pr": {"estado": "en_plazo", "limite": "2026-11-19", "etiqueta": "En plazo de promulgación"}, "fs": "2026-10-29", "ts": 1, "src": "docx"}, {"id": "ord-2842-2026", "t": "ord", "n": 2842, "y": 2026, "a": "Ampliación estacionamiento de motos", "texto": "ORDENANZA N° 2842\nVISTO:\nLa nota remitida, y la necesidad de lograr un ordenamiento en la ubicación de los estacionamientos de motos y motocicletas teniendo en cuenta los ya establecidos; y,\nCONSIDERANDO\nQue, la Ordenanza Nº2546/22 regula los espacios destinados al estacionamiento de motos;\nQue, el número de vecinos de nuestra ciudad que se trasladan en motos y ciclomotores aumenta en forma exponencial;\nQue, no se cuenta con espacios suficientes reservados para el estacionamiento de los vehículos mencionados que ofrezcan seguridad a quienes las conducen y a quienes se desplazan en la vía pública;\nQue, ante la necesidad de lograr un ordenamiento integral en materia de estacionamiento, resulta necesario contemplar los cambios y adecuaciones que surgen del uso dinámico del espacio público;\nPor ello, el Honorable Concejo Deliberante de San Andrés de Giles en uso de las atribuciones que le son propias sanciona la siguiente:\nORDENANZA\nArtículo 1º: Incorpórese al Artículo 2º la Ordenanza Nº 2546/22 los estacionamientos mencionados a continuación:\nCalle Mitre en intersección con calle Rivadavia, sobre mano izquierda.\nCalle Alsina en intersección con calle 9 de Julio, sobre mano derecha. (Ignacio Motos)\nCalle Alsina en intersección con calle Rivadavia, sobre mano derecha.\nCalle Maipú en intersección con calle Rawson, sobre mano derecha. (Básica La Campora)\nCalle Soulet en intersección con calle Pichetto, sobre mano derecha. (Verdulería)\nCalle Quintana en intersección con calle Rivadavia, sobre mano izquierda.\nArtículo 2º: De forma. -\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 15 de Octubre de 2026.-", "archivo": "2026-Ord02842 (Ampliación estacionamiento de motos).docx", "rz": "VIII", "c": "Tránsito, seguridad vial y estacionamiento", "v": "Vigente (sujeta a verificación)", "fe": "15 de octubre de 2026", "se": "Sesión Ordinaria", "vi": "La nota remitida, y la necesidad de lograr un ordenamiento en la ubicación de los estacionamientos de motos y motocicletas teniendo en cuenta los ya establecidos; y,", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 05/11/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [["Ord", 2546, "Modifica", 1]], "pr": {"estado": "tacita_presunta", "limite": "2026-11-05", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-10-15", "ts": 1, "src": "docx"}, {"id": "ord-2841-2026", "t": "ord", "n": 2841, "y": 2026, "a": "Creación del Consejo Consultivo de Bienestar Animal", "texto": "ORDENANZA N° 2841\nVISTO:\nLa necesidad de fortalecer las políticas públicas municipales vinculadas al bienestar animal, la tenencia responsable, la prevención del maltrato y la articulación entre el Estado Municipal, los rescatistas, profesionales veterinarios, instituciones intermedias y vecinos comprometidos con la temática; y\nCONSIDERANDO:\nQue la problemática vinculada al abandono, maltrato, superpoblación y falta de control sanitario de animales de compañía constituye una cuestión de interés público local\nQue el bienestar animal no debe ser abordado únicamente desde una perspectiva asistencial o reactiva, sino mediante políticas integrales de prevención, educación, castración, adopción responsable, control sanitario y participación comunitaria\nQue en nuestra comunidad existen rescatistas, colaboradores, hogares de tránsito, profesionales veterinarios y vecinos que vienen realizando una tarea comprometida y sostenida en favor de los animales, muchas veces de manera silenciosa y sin contar con un ámbito institucional adecuado de participación y articulación.\nQue resulta conveniente crear un espacio formal, plural, consultivo y honorario que permita canalizar propuestas, inquietudes, diagnósticos y recomendaciones vinculadas al bienestar animal en el Partido de San Andrés de Giles.\nQue la participación comunitaria fortalece la calidad institucional, mejora el diseño de las políticas públicas y permite que las decisiones del Estado se nutran de la experiencia concreta de quienes trabajan diariamente en el territorio.\nQue existen antecedentes de órganos consultivos y espacios de participación comunitaria que permiten articular la intervención de distintos sectores de la sociedad en asuntos de interés público local.\nQue el Honorable Concejo Deliberante constituye el ámbito natural de representación, participación ciudadana y recepción de las inquietudes de la comunidad, resultando conveniente que el Consejo Consultivo de Bienestar Animal funcione en su órbita institucional, favoreciendo el diálogo entre vecinos, organizaciones, profesionales y autoridades públicas.\nQue el Honorable Concejo Deliberante tiene la facultad de promover espacios de participación, consulta y asesoramiento en materias de interés público local.\nQue el presente Consejo no tendrá facultades decisorias ni vinculantes, ni sustituirá las competencias propias del Departamento Ejecutivo, sino que funcionará como ámbito de consulta, colaboración, seguimiento, propuesta y articulación institucional.\nQue resulta necesario dotar a dicho ámbito de reglas propias de funcionamiento, permitiendo que dicte su reglamento interno, determine su modalidad de trabajo y organice sus reuniones de manera ordenada y transparente.\nPor ello, el Honorable Concejo Deliberante de San Andrés de Giles sanciona la siguiente:\nORDENANZA\nARTÍCULO 1º. Créase el Consejo Consultivo de Bienestar Animal de San Andrés de Giles.\nEl mismo funcionará como órgano consultivo, honorario, participativo y no vinculante, destinado al asesoramiento, seguimiento, elaboración de propuestas y articulación institucional en materia de bienestar animal dentro del Partido de San Andrés de Giles.\nARTÍCULO 2º. Objeto.\nEl Consejo tendrá por objeto promover, acompañar y formular recomendaciones vinculadas a:\na) Políticas públicas de bienestar animal.\nb) Prevención del abandono y el maltrato animal.\nc) Campañas de castración, vacunación y control sanitario.\nd) Adopción responsable.\ne) Educación y concientización comunitaria.\nf) Fortalecimiento de hogares de tránsito y redes de colaboración.\ng) Condiciones de funcionamiento del refugio municipal o de los espacios municipales destinados a animales.\nh) Articulación con rescatistas, veterinarios, instituciones y vecinos.\ni) Toda otra acción vinculada a la protección, cuidado y bienestar de los animales.\nARTÍCULO 3º. Carácter no vinculante.\nLas opiniones, informes, recomendaciones, propuestas o dictámenes que emita el Consejo tendrán carácter exclusivamente consultivo y no vinculante.\nEn ningún caso el Consejo sustituirá las competencias, responsabilidades ni facultades propias del Departamento Ejecutivo Municipal ni del Honorable Concejo Deliberante.\nARTÍCULO 4º. Integración.\nEl Consejo estará integrado por:\na) Un representante del Departamento Ejecutivo Municipal.\nb) Un concejal por cada bloque político con representación en el Honorable Concejo Deliberante.\nc) Dos representantes de asociaciones de rescatistas independientes grupos o actividades vinculadas a la protección y bienestar animal debidamente inscriptos en el registro municipal de entidades de bien publico\nd) Representantes de asociaciones, grupos o entidades vinculadas a la protección y bienestar animal.\ne) Dos Médicos veterinarios matriculados con actuación en el distrito..\nTodos los integrantes desempeñarán sus funciones ad honorem.\nARTÍCULO 5º. Invitados y especialistas.\nEl Consejo podrá invitar a participar de sus reuniones, con voz pero sin voto, a funcionarios municipales, profesionales, especialistas, instituciones educativas, organizaciones no gubernamentales, fuerzas de seguridad, autoridades sanitarias o cualquier otra persona cuya intervención resulte útil para el tratamiento de los temas abordados.\nARTÍCULO 6º. Funciones\nSerán funciones del Consejo:\na) Elaborar diagnósticos y recomendaciones sobre la situación del bienestar animal en el distrito.\nb) Proponer campañas de castración, vacunación, adopción responsable y tenencia responsable.\nc) Canalizar inquietudes, propuestas y aportes de vecinos, rescatistas y entidades vinculadas.\nd) Sugerir protocolos de actuación ante casos de abandono, maltrato o emergencia animal.\ne) Promover la articulación entre el Municipio, profesionales veterinarios, rescatistas, hogares de tránsito e instituciones.\nf) Realizar recomendaciones sobre el funcionamiento y condiciones de los espacios municipales destinados al alojamiento o cuidado de animales.\ng) Elaborar informes periódicos para su elevación al Honorable Concejo Deliberante y al Departamento Ejecutivo.\nh) Proponer convenios, campañas, jornadas o programas vinculados al bienestar animal.\ni) Fomentar la educación comunitaria y la participación ciudadana.\nj) Realizar visitas, recorridas, observaciones y relevamientos en el refugio municipal y en los demás espacios municipales destinados al alojamiento, tránsito o cuidado de animales los días lunes miércoles y viernes respetando el horario municipal de 7 a 14 hs. A tales efectos, los integrantes del Consejo podrán acceder a dichos establecimientos debiendo respetar las normas de seguridad, higiene y funcionamiento del servicio.\nLas observaciones efectuadas podrán ser volcadas en informes y recomendaciones dirigidas al Honorable Concejo Deliberante y al Departamento Ejecutivo.\nk) Toda otra acción vinculada a la protección, cuidado y bienestar de los animales.\nARTÍCULO 7º. Reglamento interno.\nEl Consejo dictará su propio reglamento interno de funcionamiento, el que deberá contemplar como mínimo:\na) Periodicidad de las reuniones.\nb) Forma de convocatoria.\nc) Modalidad de participación de sus integrantes.\nd) Organización interna y elección de autoridades.\ne) Confección de actas.\nf) Régimen de informes y recomendaciones.\ng) Posibilidad de conformar subcomisiones de trabajo.\nh) Mecanismos de incorporación de nuevos integrantes.\nARTÍCULO 8º. Organización interna.\nEl Consejo elegirá de entre sus integrantes las autoridades necesarias para su funcionamiento, conforme lo establezca su reglamento interno.\nLas funciones de coordinación y conducción deberán recaer en integrantes de carácter comunitario o institucional que no ejerzan cargos políticos electivos ni funciones ejecutivas dentro del Departamento Ejecutivo Municipal.\nLos concejales y representantes del Departamento Ejecutivo participarán con voz y voto dentro del Consejo, sin perjuicio de las funciones de coordinación que establezca el reglamento interno.\nARTÍCULO 9º. Informes.\nEl Consejo deberá elevar al Honorable Concejo Deliberante, como mínimo cada seis (6) meses, un informe sobre los temas tratados, recomendaciones formuladas y acciones propuestas.\nSin perjuicio de ello, podrá emitir informes especiales cuando la gravedad o urgencia de la situación así lo requiera.\nARTÍCULO 10º. Ámbito de funcionamiento.\nEl Consejo Consultivo de Bienestar Animal funcionará en el ámbito del Honorable Concejo Deliberante de San Andrés de Giles, quien brindará el espacio institucional necesario para el desarrollo de sus reuniones, actividades y tareas de articulación comunitaria.\nARTÍCULO 11º. Participación comunitaria.\nEl Honorable Concejo Deliberante promoverá la participación de vecinos, instituciones, rescatistas, profesionales y organizaciones vinculadas al bienestar animal, fomentando el diálogo, la construcción de consensos y la articulación comunitaria en torno a las políticas públicas vinculadas a la temática.\nARTÍCULO 12º. Sin erogación presupuestaria obligatoria.\nLa creación y funcionamiento del Consejo no implicará por sí misma la asignación de remuneraciones, dietas, compensaciones ni gastos obligatorios para sus integrantes, quienes actuarán con carácter honorario.\nARTÍCULO 13º. De forma.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 15 de Octubre de 2026.-", "archivo": "2026-Ord02841 (Creación del Consejo Consultivo de Bienestar Animal).docx", "rz": "I", "c": "Consejos, comisiones y organismos asesores", "v": "Vigente (sujeta a verificación)", "fe": "15 de octubre de 2026", "se": "Sesión Ordinaria", "vi": "La necesidad de fortalecer las políticas públicas municipales vinculadas al bienestar animal, la tenencia responsable, la prevención del maltrato y la articulación entre el Estado Municipal, los rescatistas, profesionales veterinarios, instituciones intermedias y vecinos comprometidos con la temática; y", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 05/11/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [], "pr": {"estado": "tacita_presunta", "limite": "2026-11-05", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-10-15", "ts": 1, "src": "docx"}, {"id": "ord-2840-2026", "t": "ord", "n": 2840, "y": 2026, "a": "Régimen Especial de restricción del tránsito pesado", "texto": "ORDENANZA N° 2840\nVISTO\nEl artículo 27, incisos 2, 18 y 19, del Decreto-Ley N° 6769/58 - Ley Orgánica de las Municipalidades -; las Leyes Nacionales N° 24.449 y N° 25.326; la Ley Provincial N° 13.927 y sus normas reglamentarias y modificatorias; las Ordenanzas Municipales N° 1770/14 y N° 2617/23; la Comunicación N° 10/22 del Honorable Concejo Deliberante; y la necesidad de proteger la seguridad vial y la infraestructura municipal afectadas por el tránsito pesado de paso que utiliza la Avenida Lucas Scully, la calle Soldado Jorge Alfredo Maciel y el Camino de las Tropas como enlace entre la ex Ruta Nacional N° 7 y el Camino Provincial 094-01; y\nCONSIDERANDO\nQue la Ley Orgánica de las Municipalidades atribuye al Departamento Deliberativo competencia para reglamentar el tránsito, la circulación, el estacionamiento, la carga y descarga, la señalización y la ubicación de playas de maniobras y estacionamiento en calles y caminos de jurisdicción municipal;\nQue la Ordenanza N° 1770/14 regula la circulación de camiones, chasis, acoplados y bateas, cargados o vacíos, y establece arterias y condiciones específicas para el tránsito pesado en la ciudad;\nQue la Ordenanza N° 2617/23 aprobó el Código Contravencional municipal, que sanciona el tránsito pesado contrario a la reglamentación, la circulación de camiones de paso sin destino de carga o descarga y la circulación por calles o caminos excediendo su capacidad permitida;\nQue la Comunicación N° 10/22 reconoció que los sistemas de posicionamiento global y navegación digital derivan camiones de gran porte hacia el Camino Provincial 094-01 y provocan su ingreso a la ciudad desde la Ruta Nacional N° 7, y solicitó señalización en las rutas nacionales N° 7 y N° 8 y en otros puntos estratégicos;\nQue la Avenida Lucas Scully, la calle Soldado Jorge Alfredo Maciel y el Camino de las Tropas conforman un sistema de arterias municipales interconectadas que permite acceder desde la ex Ruta Nacional N° 7 al Camino Provincial 094-01;\nQue la calle Soldado Jorge Alfredo Maciel conecta la Avenida Lucas Scully con el Camino de las Tropas y, si no fuera comprendida por el mismo régimen, podría ser utilizada como recorrido alternativo para eludir parcialmente las restricciones o controles establecidos;\nQue numerosos vehículos pesados de larga distancia utilizan este sistema exclusivamente como vía de enlace entre la Ruta Nacional N° 7, el Camino Provincial 094-01 y la Ruta Nacional N° 193, aun cuando el viaje no tenga origen, destino ni operación alguna en el Partido de San Andrés de Giles;\nQue el volumen y la frecuencia de esa circulación extraordinaria aceleran el deterioro de las calzadas, banquinas y obras complementarias, reducen la vida útil de la infraestructura y elevan de manera sustancial los costos municipales de conservación y reparación;\nQue el propio Camino Provincial 094-01 presenta sectores cuyo deterioro demanda intervenciones estructurales y que, mientras estas no se ejecuten, la derivación de tránsito pesado de paso incrementa los riesgos para todos sus usuarios;\nQue las restricciones fiscales que atraviesan los distintos niveles del Estado hacen indispensable adoptar medidas preventivas y de ordenamiento que reduzcan daños evitables y permitan priorizar los recursos públicos disponibles;\nQue vecinos, productores y emprendedores de Azcuénaga han formulado reclamos reiterados por el estado del camino y por los riesgos derivados de la convivencia entre vehículos particulares, tránsito turístico, maquinaria y camiones de gran porte;\nQue se han informado accidentes, incidentes viales y daños en neumáticos, llantas y otros componentes de vehículos, situaciones que afectan la seguridad, la salud y el patrimonio de quienes utilizan el corredor;\nQue el objetivo de la presente no es impedir el abastecimiento, la producción, el desarrollo industrial, las obras, los servicios ni el acceso a establecimientos locales, sino desalentar y sancionar el uso del corredor como atajo interjurisdiccional por vehículos que carecen de una necesidad local objetiva;\nQue el Sector Industrial Planificado se encuentra en las adyacencias del Camino de las Tropas y la Playa Municipal de Camiones y la balanza municipal se ubican en el sector, por lo que deben integrar un régimen de excepciones verificables;\nQue una prohibición absoluta resultaría desproporcionada, mientras que un régimen basado en el origen o destino real del viaje, la necesidad del acceso y la utilización del recorrido más directo permite compatibilizar la protección de la infraestructura con la actividad económica local;\nQue la creación de un registro municipal permitirá identificar establecimientos, predios, vehículos y viajes autorizados y distinguirlos del tránsito pesado de paso mediante criterios generales, objetivos y auditables;\nQue las cámaras existentes, los lectores automáticos de dominio, los registros digitales y la balanza municipal pueden mejorar la fiscalización, siempre que los equipos y procedimientos cuenten con las autorizaciones exigibles y que la constatación y validación de las infracciones permanezcan bajo responsabilidad de funcionarios públicos;\nQue la señalización previa, la posibilidad de acreditar documentalmente un destino local y la intervención del Juzgado de Faltas son garantías indispensables para una aplicación razonable y jurídicamente defendible;\nQue la efectividad del régimen debe ser evaluada a partir de una línea de base y de informes periódicos que midan el tránsito, las autorizaciones, las infracciones, los incidentes y la evolución de los gastos de mantenimiento;\nQue la presente ordenanza no crea una tasa ni convierte el pago de una suma en autorización para utilizar el corredor como vía de paso, quedando cualquier eventual recurso tributario sujeto al procedimiento específico de las Ordenanzas Fiscal e Impositiva;\nQue la regulación municipal debe limitarse a las arterias de jurisdicción municipal comprendidas por la presente, sin pretender prohibir directamente la circulación sobre el Camino Provincial 094-01, respecto del cual corresponde gestionar medidas coordinadas con la Provincia de Buenos Aires;\nPor ello, el Honorable Concejo Deliberante de San Andrés de Giles sanciona la siguiente:\nORDENANZA\nARTÍCULO 1º.- Modifícase el artículo 1° de la Ordenanza N° 1770/14, el que quedará redactado de la siguiente manera:\n“ARTÍCULO 1°.- Prohíbese la circulación y el estacionamiento de camiones, chasis, con o sin acoplados, y bateas, tanto cargados como vacíos, en la vía pública de la zona urbana de la ciudad cabecera del Partido, con excepción de las siguientes arterias:\na) Acceso Colón;\nb) Avenida Nuestra Señora de Luján;\nc) Camino de las Tropas;\nd) Camino Soldado Maciel;\ne) Avenida Morgan;\nf) Avenida Lucas Scully, únicamente en el tramo comprendido entre calle Italia y Ruta Nacional N° 7;\ng) Colectora Sur;\nh) Colectora Norte;\ni) Malvinas Argentinas, únicamente en el tramo comprendido entre calle Lavalle y calle San Andrés.\nLa prohibición precedente se entiende sin perjuicio de las excepciones previstas en los artículos 2° y 3° y de las disposiciones transitorias que resulten aplicables del artículo 9° de esta Ordenanza, con las modificaciones introducidas por la Ordenanza N° 1781/14.\nLa circulación y el estacionamiento en las arterias enumeradas quedarán sujetos a las restantes disposiciones de esta Ordenanza y a los regímenes especiales aplicables. Su inclusión en la enumeración no habilita el tránsito pesado de paso en los tramos comprendidos en el artículo 1° bis, salvo las habilitaciones transitorias expresamente previstas en el respectivo régimen especial, ni el estacionamiento en lugares prohibidos por otras disposiciones.”\nARTÍCULO 2º.- Establécese un régimen especial, general y permanente de restricción del tránsito pesado de paso en la Avenida Lucas Scully, la calle Soldado Jorge Alfredo Maciel, el Camino de las Tropas y la Avenida Morgan, destinado a preservar la seguridad vial, proteger la infraestructura municipal y garantizar el acceso de los vehículos que posean un origen o destino local debidamente acreditado. Su aplicación se realizará por etapas conforme a los artículos 30, 31 y 32 de la presente.\nARTÍCULO 3º.- Quedan comprendidos en el alcance definitivo del régimen establecido por la presente, en ambos sentidos de circulación y con la aplicación por etapas prevista en el artículo 31, los siguientes tramos:\na) Avenida Lucas Scully, desde su intersección con la ex Ruta Nacional N° 7 hasta su intersección con calle Italia.\nb) Calle Soldado Jorge Alfredo Maciel, desde su intersección con la Avenida Lucas Scully hasta su intersección con el Camino de las Tropas.\nc) Camino de las Tropas, desde su intersección con la Avenida Lucas Scully hasta su intersección con el Camino Provincial 094-01.\nd) Avenida Lucas Scully, desde su intersección con la calle Nuestra Señora de Lujan hasta su intersección con el Camino de las Tropas.\ne) Avenida Morgan, en toda su extensión de jurisdicción municipal. Su individualización cartográfica deberá identificar sus extremos oficiales, incluida su intersección con la Avenida Lucas Scully.\nLa delimitación se representa en el Anexo I, que forma parte integrante de la presente y deberá distinguir los tramos y sentidos alcanzados en cada etapa y el itinerario transitoriamente habilitado. La inclusión del Camino Provincial 094-01 en los anexos es exclusivamente referencial y como criterio para determinar destinos locales; la presente no regula directamente la circulación sobre la traza provincial.\nARTÍCULO 4º.- Incorpórase como artículo 1° bis de la Ordenanza N° 1770/14 el siguiente texto:\n“ARTÍCULO 1° bis.- La habilitación general para el tránsito pesado de la Avenida Lucas Scully, del Camino Soldado Maciel, del Camino de las Tropas, del Acceso Colón y de la Avenida Morgan no comprende el tránsito pesado de paso en los tramos expresamente delimitados por la ordenanza que establece el régimen especial de restricción del tránsito pesado de paso en dichas arterias, salvo las habilitaciones transitorias y excepciones expresamente previstas en ese régimen.\nEn esos tramos resultarán exigibles la acreditación de origen o destino local, la inscripción y las autorizaciones previstas en el régimen especial, con sus excepciones, etapas y condiciones de aplicación. Tales exigencias no se aplicarán a los vehículos que circulen exclusivamente al amparo de una habilitación transitoria de paso expresamente prevista por dicho régimen, durante su vigencia y dentro del itinerario y sentido autorizados. Las restantes excepciones admitidas por esta Ordenanza no dispensan del cumplimiento del régimen especial cuando se utilice alguno de sus tramos.\nLa creación del régimen especial no amplía las excepciones previstas en los artículos 2° y 3° ni prorroga o reinicia los plazos transitorios del artículo 9° de esta Ordenanza, con las modificaciones introducidas por la Ordenanza N° 1781/14.”\nARTÍCULO 5º.- Incorpórase como último párrafo del artículo 3° de la Ordenanza N° 1770/14, en la redacción dada por la Ordenanza N° 1781/14, el siguiente:\n“Las excepciones previstas en este artículo conservarán su objeto y condiciones y no dispensarán del cumplimiento de los requisitos de origen o destino local, inscripción y autorización que resulten exigibles en los tramos sujetos al régimen especial mencionado en el artículo 1° bis, conforme a la etapa vigente. Las habilitaciones transitorias de paso expresamente previstas en dicho régimen constituirán una excepción a las prohibiciones de circulación de los artículos 1° y 3°, exclusivamente durante su vigencia y dentro del itinerario y sentido autorizados.”\nARTÍCULO 6º.- A los efectos de la presente, se consideran vehículos de tránsito pesado los camiones, chasis, con o sin acoplados, bateas, cargados o vacíos, comprendidos en el artículo 1° de la Ordenanza N° 1770/14. Quedan siempre incluidos los vehículos de carga de categorías N2 y N3, los conjuntos con remolques o semirremolques de categorías O3 y O4, los tractores de carretera, camiones articulados, bitrenes y todo vehículo o conjunto destinado al transporte de cargas cuyo peso máximo autorizado supere los tres mil quinientos kilogramos (3.500 kg), sin que este criterio excluya otros supuestos alcanzados por la Ordenanza N° 1770/14.\nARTÍCULO 7º.- A los fines de esta ordenanza, se entiende por:\na) Tránsito pesado de paso: el que utiliza total o parcialmente cualquiera de las arterias comprendidas con la finalidad exclusiva o predominante de vincular rutas o caminos nacionales o provinciales, sin efectuar una operación local real y acreditada.\nb) Origen o destino local: el establecimiento, predio, explotación, obra, instalación, localidad o dependencia municipal cuya ubicación o actividad justifique objetivamente el uso total o parcial del corredor.\nc) Operación local: la carga, descarga, retiro, entrega, abastecimiento, producción, construcción, reparación, verificación, estacionamiento operativo, pesaje, prestación de servicios u otra actividad autorizada y verificable.\nd) Acceso necesario: aquel para el cual no exista una alternativa razonable, segura y técnicamente apta para el vehículo alcanzado.\ne) Autorización: la inscripción habitual, ocasional, estacional, por obra o de emergencia emitida conforme al Registro creado por la presente.\nARTÍCULO 8º.- Prohíbese la circulación de vehículos de tránsito pesado de paso por cualquiera de las arterias y tramos definidos en el artículo 3°, conforme a las etapas y condiciones de los artículos 30, 31 y 32, salvo que exista una autorización vigente, la habilitación transitoria del artículo 31, una derivación formal de autoridad competente o una situación de emergencia debidamente acreditada. La utilización de una de las arterias alcanzadas con el objeto de evitar controles, cartelería o restricciones vigentes en otra constituirá infracción a la presente.\nARTÍCULO 9º.- Podrán circular por el corredor, previa inscripción o autorización y sin perjuicio de los supuestos de emergencia o derivación formal de autoridad contemplados en el artículo 8°, los vehículos cuyo viaje tenga origen o destino efectivo en:\na) Establecimientos radicados en el Sector Industrial Planificado de San Andrés de Giles.\nb) Establecimientos comerciales, industriales, productivos, agropecuarios, logísticos o de servicios ubicados directamente sobre la Avenida Lucas Scully, la calle Soldado Jorge Alfredo Maciel, el Camino de las Tropas, el Acceso Colón o la Avenida Morgan.\nc) Obras públicas o privadas autorizadas, predios, inmuebles o explotaciones ubicados directamente sobre cualquiera de las arterias comprendidas.\nd) Establecimientos, explotaciones, predios, inmuebles o caminos laterales vinculados con el Camino Provincial 094-01, cuando el uso del corredor resulte necesario y no exista otro acceso razonable y técnicamente apto.\ne) La localidad de Azcuénaga, únicamente cuando se acredite una operación local de carga, descarga, abastecimiento, producción, obra o prestación de servicios.\nf) Caminos rurales o laterales que se desprendan de la Avenida Lucas Scully, de la calle Soldado Jorge Alfredo Maciel, del Camino de las Tropas, del Acceso Colón, de la Avenida Morgan o del tramo de referencia del Camino Provincial 094-01, cuando su única vía de acceso apta para tránsito pesado requiera utilizar total o parcialmente el corredor.\ng) Otros establecimientos del Partido para los cuales la autoridad de aplicación determine, mediante acto fundado, que un tramo del corredor constituye el recorrido autorizado más corto, siempre que el vehículo lo abandone en la primera intersección permitida y no lo atraviese de extremo a extremo sin necesidad.\nh) La planta de Verificación Técnica Vehicular, talleres habilitados, obras de infraestructura, servicios públicos y destinos de reparación, con sujeción a las habilitaciones y condiciones de circulación que resulten aplicables conforme a la Ordenanza N° 1770/14, modificada por la Ordenanza N° 1781/14, y a la reglamentación del presente régimen.\ni) La Playa Municipal de Camiones y la balanza municipal, conforme al régimen específico del artículo siguiente.\nj) Vehículos de emergencias, seguridad, bomberos, servicios públicos, mantenimiento vial y flota municipal cuando se encuentren en cumplimiento de sus funciones.\nEl Anexo II constituye una referencia territorial y no implica la habilitación automática de todos los predios o caminos representados. Cada destino deberá ser identificado e incorporado individualmente al Registro Municipal.\nARTÍCULO 10º.- La Playa Municipal de Camiones y la balanza municipal serán destinos habilitantes únicamente cuando el ingreso tenga por objeto efectivo el estacionamiento, la guarda, la espera operativa, el control, el pesaje, el transbordo de mercadería previsto en el artículo 4° de la Ordenanza N° 1770/14, una regularización documental o una derivación dispuesta por autoridad competente, y la operación quede asentada en los registros municipales. Cuando la Playa Municipal sea el único destino invocado, la autorización comprenderá exclusivamente las arterias y el trayecto necesarios para ingresar, realizar la operación y egresar. La mera entrada o detención incidental en la Playa o en la balanza no habilitará el atravesamiento completo del corredor.\nARTÍCULO 11º.- El Sector Industrial Planificado será considerado destino local habilitante mientras no exista otro acceso oficialmente habilitado, seguro y técnicamente apto para el tránsito pesado. Si se habilitara un acceso alternativo desde la Ruta Provincial N° 41 u otra vía, el Departamento Ejecutivo deberá remitir al Honorable Concejo Deliberante un informe técnico y, si correspondiera modificar el régimen, un proyecto de ordenanza específico.\nARTÍCULO 12º.- No constituirán por sí solos origen o destino local habilitante:\na) La localidad de Solís, por contar con accesos alternativos desde las rutas nacionales N° 8 y N° 193, salvo fuerza mayor o cierre formal de esas vías.\nb) La utilización del Camino Provincial 094-01 como mero enlace entre la Ruta Nacional N° 193 y la ex Ruta Nacional N° 7.\nc) La carga, descarga o prestación de servicios en localidades o establecimientos a los que pueda accederse razonablemente por otra vía apta para tránsito pesado.\nd) Las paradas incidentales para cargar combustible, alimentarse, descansar, estacionar, reparar o realizar cualquier actividad que no constituya el objeto sustancial del viaje.\ne) El ingreso simulado o la presentación de documentación falsa, inexacta, vencida o correspondiente a otro viaje, vehículo o destino.\nLa autoridad de aplicación podrá autorizar excepcionalmente la circulación ante emergencias, fuerza mayor, interrupciones de rutas, desvíos oficialmente dispuestos o inexistencia transitoria de una alternativa segura, dejando constancia del motivo, vehículo, recorrido y plazo.\nARTÍCULO 13º.- Créase el Registro Municipal de Origen y Destino Local del Tránsito Pesado, bajo dependencia de la autoridad de aplicación, con el objeto de identificar y verificar los establecimientos, predios, vehículos, operaciones y recorridos autorizados.\nARTÍCULO 14º.- El Registro estará integrado, como mínimo, por:\na) Un Registro de establecimientos, predios, caminos y destinos habilitantes, con su ubicación georreferenciada, actividad, responsable y condiciones de acceso.\nb) Un Registro de vehículos y viajes autorizados, con identificación de la unidad tractora y, cuando corresponda, del acoplado o semirremolque, fecha o período, origen, destino, recorrido y operación.\nLa inscripción de un establecimiento no importará una autorización general e ilimitada para todos los vehículos que mantengan relaciones comerciales con él.\nARTÍCULO 15º.- La reglamentación deberá contemplar las siguientes modalidades de autorización:\na) Habitual, para operaciones regulares y reiteradas, con una vigencia máxima de un (1) año y renovación sujeta a verificación.\nb) Ocasional, para un viaje determinado o una franja temporal breve.\nc) Estacional o por obra, para cosechas, campañas, construcciones, prestaciones o actividades de duración definida.\nd) De emergencia, para fuerza mayor, interrupciones viales, desperfectos, derivaciones de autoridad o situaciones que requieran respuesta inmediata.\nLas autorizaciones serán específicas respecto del vehículo, el destino, las arterias, los tramos habilitados y el período de vigencia. No podrán transferirse a otro dominio ni utilizarse para viajes u operaciones no comprendidos en el permiso. Las autorizaciones habituales, estacionales o por obra podrán comprender las operaciones reiteradas que se individualicen en ellas. La autorización para circular por una arteria no importará habilitación automática para utilizar las restantes.\nARTÍCULO 16º.- Para obtener una autorización deberá informarse, según corresponda:\na) Identificación y domicilio del establecimiento, predio, explotación, obra o dependencia municipal.\nb) Ubicación georreferenciada, nomenclatura catastral y habilitación municipal, cuando corresponda.\nc) Identificación del transportista, titular o responsable del viaje.\nd) Dominio de la unidad tractora y del acoplado o semirremolque.\ne) Origen, destino, fecha o período, franja horaria, arterias y recorrido solicitado.\nf) Tipo general de carga, servicio u operación.\ng) Remito, carta de porte, orden de carga o descarga, turno, contrato de obra, solicitud del establecimiento receptor u otra documentación verificable.\nLa documentación podrá presentarse en soporte físico o digital. La denegación, suspensión o cancelación de una autorización deberá ser fundada y notificada. Cuando una causa objetiva hubiera impedido tramitarla previamente, el interesado podrá acreditar el origen o destino local dentro de los cinco (5) días hábiles de notificada la presunta infracción. Verificada la documentación y la causa objetiva invocada, corresponderá a la autoridad competente disponer el archivo de la actuación conforme al procedimiento aplicable, sin afectar el juzgamiento de otras infracciones que pudieran haberse constatado.\nARTÍCULO 17º.- Los vehículos autorizados deberán utilizar el recorrido más corto, directo y técnicamente apto entre el punto de ingreso y el origen o destino declarado; respetar las fechas, horarios, arterias y condiciones del permiso; evitar desvíos y detenciones ajenas a la operación; no continuar más allá del destino acreditado sin otra autorización; portar o poder exhibir la documentación respaldatoria; y someterse a los controles de identificación, peso, dimensiones, carga y seguridad que correspondan. La autorización no exime del cumplimiento de las restantes normas nacionales, provinciales y municipales.\nARTÍCULO 18º.- Será autoridad de aplicación la Dirección de Inspección General y Protección Ciudadana, o el organismo que en el futuro la sustituya, con intervención coordinada del Centro de Monitoreo Municipal, el Juzgado de Faltas, la Secretaría de Obras y Servicios Públicos y las áreas de Producción, Planeamiento, Catastro, Sistemas y Estadísticas.\nARTÍCULO 19º.- La autoridad de aplicación podrá:\na) Realizar controles fijos o móviles e interceptar vehículos en condiciones seguras.\nb) Requerir documentación física o digital y verificarla con establecimientos, bases públicas y registros municipales.\nc) Disponer el traslado a la balanza municipal cuando corresponda.\nd) Utilizar cámaras, fotografías, filmaciones, lectores automáticos de dominio y otros medios mecánicos o electrónicos admitidos por la normativa vigente.\ne) Cruzar los dominios detectados con el Registro creado por la presente.\nf) Verificar fechas, horas, etapa aplicable, sentidos de circulación, recorridos, detenciones y permanencia en cualquiera de las arterias alcanzadas.\ng) Requerir colaboración de organismos nacionales, provinciales, fuerzas de seguridad y autoridades viales.\nh) Disponer o solicitar las medidas cautelares previstas por el Código Contravencional y la legislación de tránsito.\nARTÍCULO 20º.- Autorizase al Departamento Ejecutivo a celebrar convenios y efectuar contrataciones para la provisión, instalación, integración, mantenimiento y soporte de cámaras, lectores de dominio, programas informáticos, almacenamiento y procesamiento técnico de información. Los equipos y procedimientos deberán contar con las homologaciones y autorizaciones exigibles. Los prestadores privados sólo podrán realizar tareas técnicas: la evaluación de la evidencia, la validación de la infracción, el labrado del acta y el ejercicio del poder de policía permanecerán a cargo de funcionarios públicos legalmente habilitados. Los datos obtenidos se utilizarán exclusivamente para las finalidades de esta ordenanza y deberán administrarse con medidas de seguridad, acceso restringido, trazabilidad, plazos razonables de conservación y respeto por la legislación de protección de datos personales.\nARTÍCULO 21º.- La circulación en infracción a la presente será sancionada conforme a los ítems N° 272, 273 y, cuando corresponda, 276 del Código Contravencional aprobado por Ordenanza N° 2617/23, sin perjuicio de otras infracciones concurrentes. La presentación de documentación falsa, la utilización fraudulenta de una autorización, la ocultación o alteración del dominio, la evasión de controles y la desobediencia a una orden de la autoridad serán consideradas conforme a las disposiciones específicas del mismo Código. Cuando un mismo ingreso o atravesamiento ininterrumpido sea registrado por más de un dispositivo, deberá conformarse una única actuación por la infracción de tránsito pesado de paso. Constituirán hechos independientes los nuevos ingresos realizados después de abandonar el corredor o en fechas u operaciones diferentes.\nARTÍCULO 22º.- La reincidencia se determinará de acuerdo con el ítem N° 21 del Código Contravencional. Sin perjuicio de la multa, podrá disponerse el secuestro preventivo del vehículo cuando resulte procedente conforme al Código y a la legislación nacional y provincial, especialmente ante reincidencia, documentación falsa, adulteración u ocultamiento del dominio, exceso de peso, desobediencia a la orden de detenerse o abandonar el corredor, o riesgo grave para las personas o los bienes. La constatación remota podrá dar origen a la actuación y a una orden de interceptación, pero el secuestro requerirá intervención de funcionarios autorizados y control del Juzgado de Faltas.\nARTÍCULO 23º.- Serán responsables quienes resulten alcanzados por la Ordenanza N° 1770/14, el Código Contravencional y la legislación de tránsito. La presente no modifica la obligación patrimonial solidaria prevista en el artículo 6° de la Ordenanza N° 1770/14; su procedencia y alcance deberán determinarse en cada actuación conforme a la normativa y al procedimiento aplicables.\nEn el ámbito del Registro creado por esta Ordenanza, el establecimiento o responsable registrado sólo podrá ser suspendido o excluido cuando se acredite que hubiera solicitado, consentido o validado una autorización mediante información falsa o que hubiera colaborado deliberadamente con su uso indebido. Toda suspensión o cancelación del Registro deberá ser proporcional, fundada y precedida por la posibilidad de efectuar descargo. Estas medidas registrales no sustituyen ni amplían, por sí mismas, la responsabilidad patrimonial o las sanciones que correspondan conforme a las normas aplicables.\nARTÍCULO 24º.- El Departamento Ejecutivo deberá instalar señalización visible, suficiente y anticipada en los extremos de los tramos delimitados en el artículo 3° y en los puntos seguros de decisión, retorno y control. Como mínimo, deberán señalizarse:\na) Los accesos a Avenida Lucas Scully desde la ex Ruta Nacional N° 7 y su intersección con calle Italia;\nb) Las intersecciones de la calle Soldado Jorge Alfredo Maciel con Avenida Lucas Scully y con Camino de las Tropas;\nc) Las intersecciones del Camino de las Tropas con Avenida Lucas Scully y con el Camino Provincial 094-01;\nd) Los accesos al Acceso Colón desde la Ruta Provincial N° 41 y su intersección con el Camino de las Tropas;\ne) Los extremos e intersecciones de acceso a Avenida Morgan, incluida su intersección con Avenida Lucas Scully.\nLa cartelería deberá informar las restricciones por etapa, los sentidos alcanzados, el itinerario de salida transitoriamente habilitado, las fechas y horas de inicio y finalización, las condiciones de acceso local, la existencia de controles y las sanciones aplicables. Las intervenciones se realizarán dentro de la jurisdicción municipal o, cuando correspondan a otra jurisdicción, previa autorización o actuación de la autoridad competente.\nARTÍCULO 25º.- Instrúyase al Departamento Ejecutivo a gestionar ante la Dirección Nacional de Vialidad, la Dirección de Vialidad de la Provincia de Buenos Aires y los demás organismos competentes la instalación de señalización anticipada y la definición de recorridos alternativos. Como base para la evaluación técnica deberán considerarse:\na) Para vehículos provenientes de la Autovía Nacional N° 7: la continuidad por dicha autovía o la utilización de la traza de la ex Ruta Nacional N° 7 hasta la Ruta Provincial N° 41.\nb) Para vehículos provenientes de la Ruta Nacional N° 193: el desvío por la Ruta Nacional N° 8 en dirección a la Ruta Provincial N° 6 o, en sentido contrario, hacia la Ruta Provincial N° 41.\nLos recorridos definitivos deberán ser validados por las autoridades viales competentes y podrán adaptarse a las condiciones de transitabilidad, obras y seguridad vigentes. La definición y señalización de alternativas deberá contemplar también la restricción establecida para el Acceso Colón y la Avenida Morgan, así como las etapas y el itinerario de salida transitoriamente habilitado.\nARTÍCULO 26º.- Instrúyase al Departamento Ejecutivo a comunicar la restricción, los límites georreferenciados y los recorridos alternativos aprobados a los proveedores de cartografía, logística y navegación digital, solicitando que las arterias alcanzadas dejen de ser recomendadas para vehículos de tránsito pesado sin destino local y que la prohibición sea incorporada a sus bases de datos. Las comunicaciones deberán diferenciar la primera y la segunda etapa, los sentidos de circulación y la vigencia temporal del itinerario de salida, y actualizarse al producirse el cambio de etapa.\nARTÍCULO 27º.- El área municipal competente en materia de estadísticas, conjuntamente con la autoridad de aplicación, deberá elaborar una línea de base de al menos treinta (30) días consecutivos inmediatamente anteriores al inicio de la primera etapa. Para compatibilizarla con el plazo máximo del artículo 31, el relevamiento deberá comenzar desde la promulgación o integrar registros previos verificables y comparables. Deberá quedar completado antes de la aplicación de sanciones de la primera etapa. El relevamiento registrará, como mínimo:\na) Cantidad de vehículos pesados por arteria, sentido, día y franja horaria.\nb) Categoría y configuración general de los vehículos.\nc) Origen y destino declarado mediante controles muestrales.\nd) Cantidad estimada de vehículos con y sin justificación local.\ne) Accidentes, incidentes, reclamos y daños informados.\nf) Estado inicial de las arterias y gastos recientes de conservación y reparación.\nDurante el primer año se elaborarán informes trimestrales y, a partir del segundo, informes semestrales, que compararán los resultados con la línea de base e incluirán vehículos detectados, autorizaciones, infracciones, reincidencias, medidas cautelares, incidentes y gastos de mantenimiento. Los informes serán remitidos al Honorable Concejo Deliberante y publicados en formato agregado, resguardando datos personales y comerciales. La información posterior distinguirá los resultados de la primera y de la segunda etapa, por arteria y sentido, y registrará separadamente el tránsito amparado por la habilitación transitoria del artículo 31.\nARTÍCULO 28º.- El pago de una multa, derecho, tasa o cualquier otra suma no convertirá el tránsito pesado de paso en circulación permitida. Cualquier futura tasa o derecho relacionado con servicios de control, pesaje, inspección o emisión de permisos deberá crearse mediante la Ordenanza Fiscal e Impositiva correspondiente, con identificación del servicio, sujeto obligado, base imponible y exenciones, sin superposición con tributos existentes.\nARTÍCULO 29º.- Autorízase al Departamento Ejecutivo a afectar las partidas presupuestarias necesarias para la señalización, implementación del Registro, integración de sistemas tecnológicos, controles, campañas de información, relevamientos y elaboración de estadísticas, y a gestionar asistencia técnica o financiera ante organismos nacionales y provinciales.\nARTÍCULO 30º.- Preparación y plazos. Todos los plazos de implementación se computarán en días corridos a partir de la promulgación de la presente Ordenanza y tendrán carácter máximo. El plazo de sesenta (60) días no se adicionará al de treinta (30) días.\na) Dentro de los primeros quince (15) días deberán encontrarse dictada y publicada la reglamentación operativa; habilitados el Registro y los mecanismos de autorización; instalada la señalización municipal mínima de la primera etapa; y publicada la fecha y hora de su inicio. Desde la certificación pública de esas condiciones se cumplirá un período de quince (15) días corridos de información y advertencias previo a la aplicación de sanciones de la primera etapa.\nb) Las tareas de relevamiento previstas en el artículo 27 se realizarán simultáneamente con la preparación, la inscripción y la información pública. No se exigirá que el período informativo comience una vez finalizada la línea de base;\nambos podrán superponerse, pero deberán haberse completado antes de aplicar sanciones de la primera etapa.\nc) La señalización y la comunicación del cierre del itinerario transitorio deberán estar implementadas con una anticipación mínima de quince (15) días corridos respecto del inicio de la segunda etapa y, en todo caso, dentro de los primeros cuarenta y cinco (45) días desde la promulgación. Esta comunicación no suspenderá las restricciones ni las sanciones ya aplicables en la primera etapa.\nd) Antes de iniciar las sanciones correspondientes a cada etapa, las áreas de Planeamiento, Catastro y Asesoría Letrada deberán certificar la nomenclatura, jurisdicción, extremos y continuidad de los tramos involucrados, y validar las referencias de los Anexos I y II. Se verificará especialmente la extensión de Avenida Morgan, la relación entre calle Italia y el empalme de Maciel con Scully, y la conexión de Maciel con el Camino Provincial 094-01.\nARTÍCULO 31º.- Aplicación por etapas. El régimen especial se implementará de la siguiente manera:\na) Primera etapa. Deberá comenzar dentro de los primeros treinta (30) días corridos desde la promulgación. Desde su inicio quedará prohibido el tránsito pesado de paso en las arterias y tramos delimitados en el artículo 3°, en ambos sentidos, con la única habilitación transitoria del itinerario de salida que se describe a continuación:\n1. Calle Soldado Jorge Alfredo Maciel: desde el punto de ingreso proveniente del Camino Provincial 094-01, en su vinculación con Camino de las Tropas, hasta su intersección con Avenida Lucas Scully, exclusivamente en dirección a esta última.\n2. Avenida Lucas Scully: desde su intersección con Soldado Jorge Alfredo Maciel hasta su intersección con la ex Ruta Nacional N° 7, exclusivamente en dirección a la ex Ruta Nacional N° 7.\nQuedará prohibido desde la primera etapa el tránsito pesado de paso por Scully en el sentido que parte de la ex Ruta Nacional N° 7 hacia Maciel y el camino a Azcuénaga; por Maciel en el sentido que parte de Scully hacia el Camino Provincial 094-01; y por Camino de las Tropas, Acceso Colón y Avenida Morgan en ambos sentidos dentro de los tramos comprendidos. La habilitación de salida no autoriza a recorrer longitudinalmente Camino de las Tropas ni a utilizarlo como alternativa a Maciel.\nEl itinerario transitorio deberá representarse como un recorrido continuo en el Anexo I. Exclusivamente durante su vigencia, su habilitación constituye una excepción específica a las prohibiciones de circulación de los artículos 1° y 3° de la Ordenanza N° 1770/14, en la medida estrictamente necesaria para recorrer los dos segmentos indicados; no habilita otros tramos ni sentidos. La regulación y los controles de esta Ordenanza recaerán únicamente sobre los segmentos de jurisdicción municipal.\nLos vehículos provenientes del Camino Provincial 094-01 que utilicen exclusivamente ese itinerario y sentido podrán circular sin acreditar origen o destino local ni inscribirse en el Registro por ese solo tránsito. No deberán invocar la Playa Municipal, la balanza u otro establecimiento como destino. Continuarán sujetos a los controles de identificación, documentación, pesos, dimensiones, velocidad y seguridad y a las restantes normas de tránsito aplicables.\nb) Segunda etapa. Deberá comenzar dentro de los primeros sesenta (60) días corridos desde la promulgación. En la fecha y hora publicadas para su inicio cesará la habilitación transitoria del inciso a) y quedará restringido también el tránsito pesado de paso por Maciel hacia Scully y por Scully hacia la ex Ruta Nacional N° 7, dentro del alcance definitivo del artículo 3°. La habilitación transitoria cesará, en todo caso, al cumplirse el plazo máximo de sesenta (60) días. El Departamento Ejecutivo no podrá prorrogarla mediante la reglamentación de esta Ordenanza.\nEn ambas etapas se mantendrán el Registro y las autorizaciones y excepciones previstas para los viajes con origen o destino local y los restantes supuestos expresamente admitidos. La aplicación diferenciada por sentido alcanza al tránsito pesado de paso y no convierte las arterias en vías de mano única para los demás vehículos.\nARTÍCULO 32º.- Información, fiscalización y garantías. La autoridad de aplicación publicará las fechas y horas concretas de comienzo de cada etapa y comunicará el esquema a las áreas de inspección y monitoreo, a los organismos viales competentes y a los proveedores de cartografía y navegación digital. La cartelería de la primera etapa deberá advertir expresamente la fecha y hora de finalización del itinerario de salida.\nLa aplicación de sanciones por esta Ordenanza requerirá su publicación, la señalización correspondiente, el Registro y los mecanismos de autorización operativos, el cumplimiento de los períodos de información y la validación territorial exigida en el artículo 30. Durante los períodos informativos podrán sancionarse otras infracciones graves o situaciones de peligro conforme a sus normas específicas.\nLos controles presenciales y tecnológicos deberán considerar la fecha, la hora, la etapa vigente, el tramo y el sentido de circulación. La falta de inscripción en el Registro no constituirá por sí sola infracción respecto de un vehículo comprendido en la habilitación transitoria. No podrán aplicarse sanciones retroactivas a circulaciones que, al momento de efectuarse, se encontraban permitidas por dicha habilitación.\nEl vencimiento de los plazos máximos no suplirá las condiciones previas necesarias para aplicar sanciones. Todo incumplimiento de las tareas de implementación deberá ser informado al Honorable Concejo Deliberante con sus causas y medidas correctivas, sin que ello autorice a extender la habilitación transitoria ni a alterar el alcance de las etapas.\nARTÍCULO 33º.- Comuníquese al Departamento Ejecutivo, regístrese, publíquese, dese intervención a las áreas competentes y archívese.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 15 de Octubre de 2026.-", "archivo": "2026-Ord02840 (Régimen Especial de restricción del tránsito pesado).docx", "rz": "VIII", "c": "Tránsito, seguridad vial y estacionamiento", "v": "Vigente (sujeta a verificación)", "fe": "15 de octubre de 2026", "se": "Sesión Ordinaria", "vi": "El artículo 27, incisos 2, 18 y 19, del Decreto-Ley N° 6769/58 - Ley Orgánica de las Municipalidades -; las Leyes Nacionales N° 24.449 y N° 25.326; la Ley Provincial N° 13.927 y sus normas reglamentarias y modificatorias; las Ordenanzas Municipales N° 1770/14 y N° 2617/23; la Comunicación N° 10/22 del Honorable Concejo Deliberante; y la necesidad de proteger la seguridad vial y la infraestructura municipal afectadas por el tránsito pesado de paso que utiliza la Avenida Lucas Scully, la calle Soldado Jorge Alfredo Maciel y el Camino de las Tropas como enlace entre la ex Ruta Nacional N° 7 y el ", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 05/11/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [["Ord", 1770, "Modifica", 1], ["Ord", 2617, "Refiere a", 1]], "pr": {"estado": "tacita_presunta", "limite": "2026-11-05", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-10-15", "ts": 1, "src": "docx"}, {"id": "ord-2839-2026", "t": "ord", "n": 2839, "y": 2026, "a": "Uso Conforme Ganadería Intensiva I", "texto": "ORDENANZA N° 2839\nVISTO:\nLa necesidad de reglamentar el otorgamiento de “certificado de uso conforme” para las actividades productivas referidas a la categoría GANADERÍA INTENSIVA 1, entendida como cría y/o engorde de animales (ovino, bovino, equino, caprino, apicultura, avicultura) bajo un sistema de producción intensiva, en una superficie menor y asociadas a productores familiares o pequeños productores, hasta una cantidad máxima de animales; y\nCONSIDERANDO:\nQue existen en la localidad de San Andrés de Giles, establecimientos productivos que encuadran en dicha actividad, localizados en áreas con diferentes impactos en el ordenamiento local, definido por el Código de Ordenamiento Urbano y Territorial Vigente.\nQue, es responsabilidad del Estado impulsar los mecanismos necesarios para la incorporación y reglamentación de actividades productivas asociadas a la producción intensiva (baja escala e impacto) , vinculadas a formas de producción animal de pequeña escala, históricamente desarrolladas en el ámbito rural local, asociadas principalmente al trabajo familiar , las economías de cercanía y la generación de ingresos complementarios, para numerosas familias que habitan en ese medio.\nQue, el Municipio de San Andrés de Giles trabaja a favor del desarrollo productivo local, apoyando, potenciando y fortaleciendo las actividades de nuestros vecinos; afianzando de esta manera, el crecimiento de dichas actividades , que tan arraigadas se encuentran en nuestro medio.\nQue el primer objetivo general definido por el Plan Estratégico de Desarrollo Rural (Ordenanza 745/2002) dice:”… estructurar el Área Rural del Partido a fin de mejorar las condiciones de vida de la población, preservando los recursos ambientales e impulsando el desarrollo de actividades productivas.”.\nQue las nuevas actividades definidas por el COUyT como “Ganadería Intensiva 1 (actividad comprendida como cría y/o engorde de animales (ovino, bovino, equino, caprino, apicultura, avicultura) bajo un sistema de producción intensiva en una superficie menor y asociados a productores familiares o pequeños productores, hasta una cantidad máxima de animales , deben ser reglamentadas por Ordenanza , estableciéndose las condiciones para poder encuadrarse en la presente Categoría”, conforme lo establecido por el COUyT vigente aprobado por Ordenanza Nº 2551/2022, que prevé dicha reglamentación desde su sanción.\nQue obran en las presentes actuaciones, dictámenes de la Dirección de Producción, Dirección de Ambiente ,Dirección de Planeamiento y Obras Particulares, como asi también del Asesor Letrado del Municipio, de los cuáles surge la factibilidad de acceder a la petición incoada.\nQue, la presente medida se dicta en uso de las atribuciones conferidas por la Ley Orgánica de Municipalidades, Decreto Ley N° 6769/58 y sus modificatorios y el Decreto N° 2199/77 y modificatorios;\nPor ello, el H.C.D. en uso de atribuciones que le son propias, sanciona la siguiente:\nORDENANZA\nArtículo 1°: Establécese las siguientes exigencias para el otorgamiento del Uso Conforme para GANADERÍA INTENSIVA 1 (pequeños productores-productores familiares).\nDocumentación a acreditar:\n• Nota dirigida al Intendente Municipal solicitando la actividad especificando:\nNomenclatura Catastral\nActividad que desarrolla\nAño de inicio de la actividad\nTitular de la parcela y del emprendimiento\nSuperficie (m²) que pretende habilitar\nMano de obra afectada a la actividad (familiar y/o externa)\nDatos del solicitante: Nombre – Apellido – DNI – Tel. del contacto\n• Adjuntar:\nMemoria descriptiva\nDocumentación que certifique la actividad/fotografías.\nFotocopia de título de propiedad, contrato de locación de la parcela o autorización expresa del propietario de la parcela para el desarrollo de la actividad.\nLibre deuda de tasas municipales.\nDos fotos por cada módulo de producción.\nFotocopia del DNI del solicitante\nToda aquella documentación complementaria que defina el área del Departamento Ejecutivo con incumbencias.\nPlan anual sanitario firmado por un veterinario.\nArtículo 2°: Los emprendimientos productivos se categorizan según el tipo de actividad:\na. Producciones PORCINAS:\nLa actividad deberá desarrollarse contemplando una superficie mínima de cinco metros cuadrados (5 m²) por madre con cría durante la etapa de gestación y de dos metros cuadrados (2 m²) por animal durante las etapas de recría y engorde, en instalaciones cubiertas. Serán consideradas pequeñas productoras aquellas explotaciones que cuenten con un plantel de hasta treinta (30) madres en ciclo completo o hasta trescientos (300) lechones por ciclo en aquellas actividades que desarrollen exclusivamente las etapas de engorde o terminación. Los predios destinados al desarrollo de la actividad deberán contar con una superficie de hasta treinta (30) hectáreas y podrán comprender las etapas de cría, recría, engorde/terminación, ciclo completo o una combinación de ellas. Asimismo, deberán contar con cortinas forestales perimetrales destinadas a resguardar el establecimiento y mitigar los impactos propios de la actividad. Un plantel de hasta treinta (30) madres será considerado el umbral máximo para determinar que la explotación constituye una empresa de base familiar.\nEl modo de crianza será con cama y sin piletones. En el sistema semi-intensivo los animales gozan varias horas al día de la explotación al aire libre, mientras que en otras horas o época se mantienen en espacios cerrados (estabulación) sometidos a una alimentación intensiva. Este sistema busca combinar los beneficios de la producción intensiva y la producción extensiva, teniendo en cuenta el bienestar animal y fomentando las producciones familiares y a los productores pequeños. Este tamaño permite generar ingresos suficientes para sostener un núcleo familiar, requiriendo principalmente la mano de obra de sus propios miembros (1 o 2 personas), con eventual ayuda temporal. Superar las 30 madres obliga a dar un salto de escala: requiere contratación permanente de peones, mayor capitalización, estructura contable y entra en la lógica de rentabilidad del sector agropecuario de escala media.\nb. Producciones BOVINAS:\nActividad que contempla hasta dos (2) vacas lecheras por hectárea y entre tres (3) y siete (7) bovinos destinados a cría y/o engorde (novillos) por hectárea, dependiendo de la aptitud del suelo y la disponibilidad de la parcela, desarrolladas en predios de hasta treinta (30). La cantidad de animales por hectárea dependerá de la categoría animal llevada a cabo en la actividad. La producción deberá contar con cortinas forestales perimetrales destinadas a resguardar y mitigar los impactos propios de la actividad.\nLa producción semi-intensiva bovina combina el pastoreo con la suplementación estratégica, utilizando infraestructura básica como alambrados, corrales y aguadas. Este sistema busca optimizar la productividad mediante el manejo del rodeo, la planificación forrajera, la sanidad y la genética, promoviendo esquemas de producción de baja escala compatibles con el entorno y orientados a productores familiares o pequeños productores.\nc. Producciones AVÍCOLAS:\nActividad que contemple hasta 2.500 gallinas desarrolladas en predios de hasta cinco (5) hectáreas, con acceso tanto a áreas al aire libre como a áreas cubiertas en galpones móviles, contemplando un bebedero cada ocho gallinas. La producción pastoril deberá desarrollarse mediante sistemas de pastoreo rotativo y contar con cortinas forestales perimetrales destinadas a resguardar y mitigar los impactos propios de la actividad. Este sistema semi intensivo comprende tanto a la actividad de gallinas ponedoras como así a la actividad de pollos para engorde. Para la producción de gallinas ponedoras la cantidad de aves deberá guardar relación con la superficie efectivamente destinada al pastoreo, estableciéndose como referencia una superficie mínima de veinte metros cuadrados (20m²) por gallina. Para la producción de pollos destinados a carne se admitirá la instalación de galpones de hasta trescientos metros cuadrados (300 m²) de superficie cubierta por unidad productiva.\nDe este modo se permite que las gallinas tengan acceso a pastoreo rotativo y a un espacio protegido contra el clima y los depredadores, combinando los beneficios de la producción intensiva con el bienestar animal y la posibilidad de pastoreo. Un gallinero móvil es un refugio ligero para gallinas diseñados para ser movidos fácilmente de un lugar a otro para que las aves puedan pastar en diferentes áreas y obtener una alimentación más natural, mejorando su bienestar y la salud del suelo. Generalmente no tienen suelo lo que permite que las gallinas escarben en la tierra y tengan acceso a insectos y a otros alimentos naturales, actividad física, fomentando la producción de gallinas más saludables, que reduce el estrés aviar y la necesidad de uso preventivo de antibióticos, mejorando drásticamente la calidad del huevo o la carne. Cabe mencionar que este sistema se puede adaptar a cualquier tipo de crianza y espacio.\nd. Producciones OVINA Y CAPRINA:\nActividad que contempla hasta diez (10) ovejas por hectárea, tanto para carne, lácteos, lana y/o cuero, dependiendo del estado actual de la parcela, y diez (10) caprinos por hectárea en condiciones equivalentes, desarrolladas en predios de hasta treinta (30) hectáreas debiendo contar con cortinas forestales perimetrales destinadas a resguardar y mitigar los impactos propios de la actividad.\nLa producción semi-intensiva de caprinos y ovinos combina el pastoreo y la suplementación con forrajes y concentrados, utilizando infraestructura básica como corrales y aguadas. Este sistema busca optimizar la productividad con manejo del hato, pastizales, genética y sanidad.\ne. Producciones primarias EQUINAS:\nActividad que contempla un caballo por hectárea a campo.\nf. Producciones APÍCOLAS:\nActividad apícola basada en la instalación de hasta veinticinco (25) colmenas destinadas a la producción de miel y otros subproductos, cuya localización no se regirá por criterios de densidad por hectárea sino por condiciones territoriales y ambientales.\ng. Producciones CUNÍCOLAS:\nActividad que contemple hasta 100 madres reproductoras y realicen la actividad de cría y/o engorde de conejos destinados a la producción de carne, desarrollado en predios de hasta cinco (5) hectáreas, mediante sistemas de producción en jaula, conejeras o instalaciones de alojamiento colectivo que garanticen condiciones adecuadas de bienestar animal, higiene, ventilación, protección frente a las condiciones climáticas y los depredadores, y facilidad para las tareas de manejo y limpieza. La cantidad de animales deberá guardar relación con la capacidad efectiva de las instalaciones destinadas a su alojamiento, evitando situaciones de hacinamiento y garantizando espacio suficiente para el desplazamiento, descanso y comportamiento natural de los animales. Debiendo contar con cortinas forestales perimetrales destinadas a resguardar y mitigar los impactos propios de la actividad.\nArtículo 2 bis: Producciones MIXTAS: Se consideran producciones mixtas aquellas explotaciones que desarrollen simultáneamente dos o más de las actividades productivas contempladas en el presente artículo, dentro de un mismo establecimiento.\nA los efectos de determinar la capacidad productiva máxima admisible, se establece un Índice de Producción Mixta (IPM), que permitirá integrar las diferentes actividades mediante la sumatoria de las proporciones correspondientes a cada una de ellas.\nEl índice se calculará mediante la siguiente fórmula:\nIPM = Σ (Qi / Qmáxᵢ) ≤ 1\nDonde:\nQi: cantidad de animales o unidades productivas correspondientes a cada actividad.\nQmáxᵢ: cantidad máxima admisible para dicha actividad, determinada conforme a los límites, densidades, superficies y demás condiciones establecidas en los incisos precedentes.\nLa sumatoria de las proporciones correspondientes a las distintas actividades no podrá superar la unidad (1), equivalente al cien por ciento (100 %) de la capacidad productiva máxima admitida.\nQuedan exceptuadas del cálculo del Índice de Producción Mixta las producciones apícolas, las cuales podrán desarrollarse conjuntamente con cualquiera de las demás actividades productivas, sin afectar la capacidad máxima admisible de estas, debiendo respetar el límite de veinticinco (25) colmenas por establecimiento y las condiciones de localización, manejo y seguridad que correspondan.\nEn ningún caso la aplicación de este índice eximirá del cumplimiento de los requisitos particulares de cada actividad, incluyendo las superficies mínimas por animal, las instalaciones, las condiciones de manejo, el bienestar animal, las cortinas forestales y las medidas de protección ambiental.\nCuando se desarrollen actividades que compartan superficies de pastoreo, la autoridad de aplicación deberá evaluar la carga animal conjunta, a fin de evitar situaciones de sobrepastoreo o degradación del suelo.\nLa autoridad de aplicación podrá requerir un esquema de distribución de las actividades dentro del predio y establecer restricciones adicionales debidamente fundadas en función de la aptitud del suelo, la disponibilidad de recursos y los impactos ambientales acumulativos.\nArtículo 3°: Los Certificados de Uso Conforme se otorgarán conforme a las tipologías definidas en el artículo 2° y respecto de la parcela declarada al momento de la solicitud.\nCuando el titular pretenda modificar las características de la actividad originalmente declarada, la escala productiva, la superficie afectada o cualquier otra\ncondición que hubiera sido considerada para el otorgamiento del Certificado de Uso Conforme, deberá presentar un informe describiendo las modificaciones propuestas y las características de la producción y su entorno, a fin de que la autoridad de aplicación evalúe la procedencia de emitir un nuevo Certificado de Uso Conforme de acuerdo a las nuevas condiciones del emprendimiento.\nArtículo 4°: En las actividades comprendidas dentro de la presente Ordenanza, deberá contemplarse la proximidad a viviendas existentes, establecimientos vecinos y demás usos linderos, para poder evaluar la implantación de la actividad en relación con su entorno. La autoridad de aplicación podrá establecer distancias, porcentajes de ocupación, áreas de resguardo u otras medidas de mitigación que considere necesarias según las características de cada caso particular.\nArtículo 5°: Las cortinas forestales exigidas en el marco de la presente Ordenanza deberán ejecutarse conforme a las condiciones ambientales y territoriales del sector donde se emplacen. La determinación de las especies vegetales, densidad, disposición y demás características técnicas de dichas barreras deberá consensuar con las autoridades competentes, la cual emitirá las recomendaciones y/o lineamientos correspondientes para cada caso particular.\nArtículo 6°: Dése difusión a las disposiciones de la presente, a través de los medios que el Departamento Ejecutivo estime conveniente.\nArtículo 7°: Créase el Registro Municipal de Ganadería Intensiva 1 – Pequeños Productores, en el cual deberán inscribirse todas aquellas actividades comprendidas dentro de las categorías establecidas en la presente Ordenanza, como requisito previo para el otorgamiento y mantenimiento del Certificado de Uso Conforme. El mismo estará a cargo de las áreas que el Departamento Ejecutivo determine con incumbencia en la materia.\nArtículo 8°: La inscripción al registro será acreditada a través de la emisión de un Certificado de la autoridad de aplicación, el cual contendrá un número de registro, y que implica el otorgamiento de la inscripción de la actividad.\nArtículo 9°: El Departamento Ejecutivo deberá prever la asignación de los recursos humanos, técnicos, materiales, logísticos y presupuestarios necesarios para garantizar el efectivo cumplimiento de las funciones de evaluación, inspección, seguimiento y control previstas en la presente Ordenanza, adoptando las medidas administrativas que resulten necesarias para su implementación.\nArtículo 10°: En caso de verificarse que las características y requisitos tenidos en cuenta al momento de la inscripción hayan sido modificados de modo tal que el emprendimiento deje de encuadrarse dentro de las condiciones establecidas para la categoría Ganadería Intensiva 1, la autoridad de aplicación intimará al titular para que, dentro del plazo de ciento veinte (120) días corridos contados desde la notificación fehaciente, regularice su situación, gestione el Certificado de Uso Conforme correspondiente a la categoría que resulte aplicable o proceda a la relocalización de la actividad, según corresponda. Vencido dicho plazo sin que el titular haya dado cumplimiento a lo intimado, el Departamento Ejecutivo dejará sin efecto la inscripción en el Registro Municipal creado por la presente Ordenanza y comunicará dicha circunstancia al organismo competente para el otorgamiento de la habilitación o autorización correspondiente, informando que la actividad carece de Certificado de Uso Conforme vigente.\nArtículo 11°: De forma.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 15 de Octubre de 2026.-", "archivo": "2026-Ord02839 (Uso Conforme Ganadería Intensiva I ).docx", "rz": "VI", "c": "Producción agropecuaria y ruralidad", "v": "Vigente (sujeta a verificación)", "fe": "15 de octubre de 2026", "se": "Sesión Ordinaria", "vi": "La necesidad de reglamentar el otorgamiento de “certificado de uso conforme” para las actividades productivas referidas a la categoría GANADERÍA INTENSIVA 1, entendida como cría y/o engorde de animales (ovino, bovino, equino, caprino, apicultura, avicultura) bajo un sistema de producción intensiva, en una superficie menor y asociadas a productores familiares o pequeños productores, hasta una cantidad máxima de animales; y", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 05/11/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [], "pr": {"estado": "tacita_presunta", "limite": "2026-11-05", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-10-15", "ts": 1, "src": "docx"}, {"id": "ord-2838-2026", "t": "ord", "n": 2838, "y": 2026, "a": "Cesión de parcela a VETSAG SRL", "texto": "ORDENANZA N° 2838\nVISTO:\nEl expediente n° 4101-26600/26 caratulado: VETSAG S.R.L. s/ cesión de parcela, y\nCONSIDERANDO:\nQue a través del mismo, el Sr. Damián Ismael Vettorazzo, en su carácter de socio gerente de la firma VETSAG S.R.L., solicita la modificación de la ordenanza n° 2306/20.\nQue la citada ordenanza, versa sobre la cesión gratuita a la firma PERIMETRALES SAN ANDRES S.A. - en formación- representada por el Sr- Damián Vettorazzo, de una fracción identificada como Circ. II, Secc. C, Fracción Il, Parcela 8 ubicada en el S.I.M., donde la empresa montaría su fábrica dedicada a la construcción de alambrados perimetrales para su venta mayorista y minorista, postes de hormigón y accesorios para alambrados.\nQue en fecha 02.12.2020 se suscribió la pertinente \"Acta-Acuerdo de entrega de parcela\" entre la Municipalidad de San Andrés de Giles y la firma mencionada.\nQue, con fecha 5 de agosto pasado, el Sr. Damián Vettorazzo, informa al Municipio sobre una situación acaecida en la constitución social de la firma, la cual ha cambiado de denominación recientemente.\nEn efecto, primigeniamente, la sociedad, dedicada a la fabricación de alambrados perimetrales para su venta mayorista y minorista, se constituyó con el nombre de PERIMETRALES SAN ANDRES S.A. - en formación-, representada por el requirente, quién aclara que ese proyecto societario no pudo concretarse bajo esa forma jurídica ni con esa razón social, procediéndose posteriormente a la constitución de la firma VETSAG SRL, actualmente vigente.\nLas dos sociedades se constituyeron con los mismos integrantes.\nQue, se trata del mismo proyecto productivo, manteniéndose el mismo objeto, localización y conducción, habiéndose desarrollado la actividad, conforme el destino previsto.\nQue por circunstancias de incumbencia personal de los integrantes de esa sociedad, la misma ha cambiado de denominación, pasando a denominarse VETSAG SR.L., manteniendo las mismas características que su antecesora.\nQue obra en las actuaciones, dictamen de la Sra. Directora de Producción del Municipio, del cual surge que resulta procedente reconocer administrativamente el\ncambio de razón social, por entender que dicha modificación no altera el objeto del proyecto, ni el destino productivo previsto.\nQue ha sido analizada la documentación perteneciente a la última constitución, no encontrándose objeciones legales que formular, según surge del dictamen elaborado por el Sr. Asesor Letrado del Municipio.\nQue, en virtud de los antecedentes colectados, resulta procedente resolver favorablemente la petición incoada.\nPor ello, el Honorable Concejo Deliberante de San Andrés de Giles en uso de sus atribuciones, aprueba la siguiente:\nORDENANZA\nArtículo 1°: Derogar los artículos 2ª, 3°, 4°, 5°, 6°, 7° 8° y 9° de la ordenanza n° 2306/20. Sancionada por este Honorable Concejo Deliberante con fecha 12.11.2020. , quedando plenamente vigentes los artículos 1° y 10° de la citada norma legal.\nArtículo 2°: Autorizar al D.E. a ceder gratuitamente a la firma VETSAG S.R.L., representada por el Sr. Damián Vettorazzo DNI n° 29.178.295 CUIT n° 20-29178295-8 con domicilio en calle Manchi y 52 de la localidad de San Andrés de Giles, la fracción identificada con la siguiente nomenclatura catastral: Circunscripción II, Sección C,\nFracción II, Parcela 8, según proyecto de subdivisión que se acompaña-comprendida en la Zona Industrial Exclusiva- encerrando una superficie de 2.767,15 m2. Aproximados, con cargo a ser destinada a la instalación de una fábrica de alambrados perimetrales para su venta mayorista y minorista, adicionando postes de hormigón y accesorios para alambrados.\nArtículo 3°: El Departamento Ejecutivo procederá mediante acto administrativo a la entrega de la parcela cedida en un plazo no mayor a los 30 días, contados a partir de la promulgación de la presente ordenanza\nArtículo 4º: Disponer que si la empresa sesionada cambiase el destino acordado al inmueble cedido y/o no iniciara las obras correspondientes en un plazo máximo de un año y/o no obtuviera la habilitación definitiva en un plazo máximo de tres años, (pudiéndose extender este plazo por demoras exclusivas del Organismo competente a la habilitación en cuestión), ambos plazos contados a partir de la fecha de entrega de la parcela, caducara de inmediato la respectiva cesión gratuita estipulada en el artículo precedente, operándose la revocación de la cesión de pleno derecho y sin necesidad de interpelación previa de ninguna índole, reingresando el inmueble en cuestión al patrimonio de la Municipalidad, quedando a favor de ésta las instalaciones existentes en el mismo, sin derecho a indemnización por parte de los beneficiarios.\nArtículo 5: Queda expresamente establecido que la cesión a efectuarse como consecuencia de lo dispuesto en el Artículo 1°, se hallara condicionada a la aceptación y\ncumplimiento por parte del beneficiario de todas las normas Nacionales, Provinciales y Municipales vigentes, así como las que rijan la futura concreción del Sector Industrial Planificado que proyecta para el área de emplazamiento de la superficie objeto de esta Ordenanza y que se constituyen un objetivo de interés general, impulsado por la Municipalidad de San Andrés de Giles. El incumplimiento de tal condición producirá iguales efectos que los establecidos en el artículo precedente respecto de la revocación del otorgamiento.\nArtículo 6°: El Departamento Ejecutivo deberá dejar expresamente manifestado que, pese a las gestiones que se realizan en el Sector Industrial Planificado, donde se encuentran ubicadas las parcelas objeto de la cesión que establece la presente Ordenanza, aún no existe tendido de red de gas, ni de línea telefónica. Asimismo, se deberá expresar que el sector cuenta con calles Interiores consolidadas con tosca y piedra y con cordón cuneta y que no se puede garantızar por parte de la Municipalidad, la potencia eléctrica que su actividad requiera. Igualmente, deberá explicitar de manera inequívoca que las Autoridades Provinciales aún no se han expedido sobre la factibilidad hidráulica del suelo y no ha sido aprobado el plano de subdivisión que crea el lote en cuestión. La beneficiaria deberá aceptar de manera fehaciente las condiciones que recibe el inmueble y manifestar que no tendrá derecho a reclamar ningún tipo de indemnización a la Municipalidad de San Andrés de Giles, por eventuales daños y perjuicios por la ausencia de las mejoras y/o la inexistencia de resoluciones administrativas que impida la consecución del proyecto productivo de sus empresas en el lugar. En el supuesto de no poder la cesionaria llevar adelante el emprendimiento por las causales indicadas u otras de cualquier naturaleza, la Municipalidad podrá revocar la donación, notificando aquella su voluntad rescisoria con una anticipación de seis meses.\nArtículo 7°: Establecer que la escritura traslativa de dominio será instrumentada dentro de 90 (noventa) días contados a partir de la aprobación del plano de subdivisión del terreno y en oportunidad de lo requiera la empresa cesionaria de la fracción. Que los gastos que demande el otorgamiento de la respectiva escritura traslativa de dominio será por cuenta exclusiva de la empresa beneficiaria.\nArtículo 8°: Estipular que una vez escriturado el inmueble por parte de la empresa, esta dispondrá de todos los derechos inherentes a la posesión y al dominio del bien en cuestión y que pondrá enajenarlo una vez consolidado el dominio a través del cumplimiento de los cargos reglados en la presente Ordenanza.\nArtículo 9°: Autorizar al D.E. a suscribir cuanta documentación resultare necesaria para dar cumplimiento a lo determinado en la presente Ordenanza.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 15 de Octubre de 2026.-", "archivo": "2026-Ord02838 (Cesión de parcela a VETSAG SRL ).docx", "rz": "III", "c": "Dominio municipal, catastro y transferencias", "v": "Vigente (sujeta a verificación)", "fe": "15 de octubre de 2026", "se": "Sesión Ordinaria", "vi": "El expediente n° 4101-26600/26 caratulado: VETSAG S.R.L. s/ cesión de parcela, y", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 05/11/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [["Ord", 2306, "Deroga parcialmente", 1]], "pr": {"estado": "tacita_presunta", "limite": "2026-11-05", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-10-15", "ts": 1, "src": "docx"}, {"id": "ord-2837-2026", "t": "ord", "n": 2837, "y": 2026, "a": "Convenio con anestesiólogos", "texto": "ORDENANZA N° 2837\nVisto:\nEl expediente Nº 4101-24865 -2025, caratulado: Secretaria de Salud s/ convenio Asociación de Anestesiología del Norte de la Provincia de Buenos Aires; y\nConsiderando:\nQue la Sra. Secretaria de Salud del Municipio ha manifestado la necesidad de renovar el convenio oportunamente suscripto con la Asociación de Anestesiología del Norte de la Provincia de Buenos Aires, aduciendo la buena experiencia con la Asociación, habiendo cumpliendo satisfactoriamente con las obligaciones pactadas, sin observarse ningún tipo de conflicto o circunstancia adversa.\nQue el objetivo de la renovación de dicho convenio, obrante en las presentes actuaciones, es la continuación de la realización de prácticas de anestesiología, analgesia y reanimación, por parte de los Asociados a la misma, durante las 24 horas del día, por el plazo de duración del convenio, de acuerdo a las necesidades del servicio de salud pública del Hospital Municipal San Andrés.\nQue, la implementación del aludido convenio, tendría por finalidad, suplir la escasez de profesionales de la rama mencionada, en el nosocomio local, que se viene acrecentando con el correr del tiempo, debido a la falta de formación y especialización de los médicos, carga de trabajo excesiva de los que eligieron la especialidad y otros factores que contribuyen a la insuficiencia de anestesistas en hospitales públicos, lo que puede afectar la calidad de la atención médica y la seguridad de los pacientes.\nQue, sumado a este contexto, se encuentra el hecho que las prestaciones de las distintas especialidades que se brindan en el Hospital Municipal San Andrés se han incrementado notoriamente, debido al acrecentamiento de la población sostenida en el tiempo y a que resulta ser el único efector de salud en todo el Partido, como así también la complejidad de su funcionamiento dado por la diversa naturaleza de los servicios que brinda.\nQue la falta de médicos anestesiólogos, constituye una circunstancia excepcional que compromete la continuidad y seguridad de las prestaciones sanitarias esenciales, dificultando la realización de cirugías programadas, urgencias, partos, cesáreas y procedimientos que requieren anestesia general o regional.\nLa situación detallada, genera un riesgo sanitario al limitar la capacidad de respuesta del sistema de salud, frente a urgencias médicas, pudiendo ocasionar demoras en la atención, necesidad de derivaciones fuera del distrito y afectación al derecho de acceso a la salud de la población.\nQue es un deber ineludible de la administración municipal, brindar a los vecinos de San Andrés de Giles un óptimo servicio hospitalario en todas las especialidades, asegurando a los pacientes internados y ambulatorios la cobertura total y la adecuada atención de su salud, las 24 horas del día, los 365 días del año.\nQue el Hospital Municipal San Andrés no cuenta con recursos profesionales suficientes, que permitan cubrir en forma óptima las demandas del servicio de anestesiología, de acuerdo a las necesidades reales que determina la casuística actual y a efectos de no resentir la calidad de las prestaciones hospitalarias y que la población no se vea afectada desde el punto de vista médico-sanitario, se ha ideado la suscripción de un convenio, a fin de resolver con la premura que la situación amerita, la misma.\nCon fecha 13 de noviembre próximo pasado, el H.C.D., sancionó la ordenanza n° 2780/25 a través de la cual se declara la Emergencia Sanitaria en el ámbito del Partido de San Andrés de Giles, facultando al Departamento Ejecutivo a adoptar las medidas urgentes necesarias, para garantizar la continuidad de los servicios de salud.\nQue, se considera de vital importancia resolver en forma inmediata la situación descripta, considerando que la implementación de este convenio, coadyuvará a continuar la prestación de los servicios de salud en nuestro querido hospital.\nQue del informe elaborado por la Sra. Contadora Municipal Interina, surge que en caso de ser necesario generar gastos, deberá requerirse intervención previa de esa área, a efectos de dictaminar sobre la capacidad financiera y/o presupuestaria de la Municipalidad para afrontarlos.\nQue en virtud de lo expresado por el artículo 41º y el artículo 273º de la LOM, corresponde remitir el expediente al Honorable Concejo Deliberante a efectos de la Homologación del convenio oportunamente suscripto.\nQue ha intervenido en las presentes actuaciones, el Sr Asesor Letrado Municipal, informando que no existen objeciones legales para la homologación del convenio.\nPor ello el Honorable Concejo Deliberante en uso de las facultades legales que le son propias, sanciona la siguiente:\nORDENANZA\nARTICULO 1º: Homologar el convenio suscripto entre la Municipalidad de San Andrés de Giles y los médicos especialistas en anestesiología, Dras. Isis Valentina del Valle Bellorin Verenzuela, DNI 96.234.559, M.P. n° 65682, y el Dr. Sergio Daniel Casado, DNI 32.610.081, M.P. Nº232358; en su carácter de Asociados a la Asociación de Anestesiología del Norte de la Provincia de Buenos Aires, el que obra en fs. 65, 66 y 67 del expediente nº 4101-24865/25, cuyo objeto es la realización de prácticas de anestesiología, analgesia y reanimación, por parte de los Asociados a la misma, durante las 24 horas del día, por el plazo de duración del convenio, de acuerdo a las necesidades del servicio de salud pública del Hospital Municipal San Andrés.\nArtículo 2º: Autorizar al Departamento Ejecutivo, a afectar fondos que excedan el presente ejercicio y a introducir las modificaciones presupuestarias que resulten necesarias, con el fin de afrontar la atención de los gastos que se generen, producto de la\nobligación asumida por el contrato objeto de la presente, hasta la finalización de la vigencia del mismo.\nArtículo 3°: Autorizar al Departamento Ejecutivo a realizar todas las tramitaciones necesarias y a suscribir cuanta documentación resulte pertinente para el cumplimiento del objeto de la presente.\nArtículo 4º: Registrar. Comunicar a las áreas pertinentes en virtud de la naturaleza de la presente norma. Comunicar y archivar.\nDada en Sesión Especial celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 7 de Octubre de 2026.-", "archivo": "2026-Ord02837 (Convenio con anestesiólogos ).docx", "rz": "VII", "c": "Salud pública y hospital municipal", "v": "Vigente (sujeta a verificación)", "fe": "7 de octubre de 2026", "se": "Sesión Especial", "vi": "El expediente Nº 4101-24865 -2025, caratulado: Secretaria de Salud s/ convenio Asociación de Anestesiología del Norte de la Provincia de Buenos Aires; y", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 29/10/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [], "pr": {"estado": "tacita_presunta", "limite": "2026-10-29", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-10-07", "ts": 1, "src": "docx"}, {"id": "ord-2836-2026", "t": "ord", "n": 2836, "y": 2026, "a": "Incremento Salarial", "texto": "ORDENANZA N° 2836\nVisto:\nEl Decreto Nº 1434/2026 dictado por el Departamento Ejecutivo con fecha 11 de septiembre del año en curso- ad-referéndum de su convalidación por parte del Honorable Concejo Deliberante; y\nConsiderando:\nQue el referido acto administrativo dispone otorgar a partir del 1º de septiembre de 2026 un incremento salarial del siete por ciento (7%) al salario básico del mes de agosto de 2026 pagadero con los haberes del mes de septiembre de 2026 en los sueldos básicos vigentes de las clases comprendidas desde la categoría 2 a categoría 24 inclusive respecto de lo autorizado presupuestariamente para el ejercicio 2026 , efectuando la consecuente adecuación de los artículos y anexos de la Ordenanza Nº 2783/25 (Decreto 1899/25) que se verían afectados; teniendo en cuenta las modificaciones introducidas oportunamente mediante Decreto 1131/2026 (De1297/2026-Ordenanza Nº 2821/2026) y establecer el nuevo anexo que forma parte integrante del Decreto mencionado en el visto; .\nQue el artículo 2º del acto, contempla adecuar las remuneraciones establecidas por el Artículo Nº 2 del Decreto Nº 1131/2026 aprobado y prestado conformidad por Ordenanza 2821/2026(DE Nº 1297/2026) modificatorio de los Artículos 6º, 7º y 10º de la Ordenanza Nro. 2783/25 (promulgada por Decreto 1899/25) en función del artículo precedentemente mencionado.\nQue se considera atendible el reclamo oportunamente formuladas por las entidades gremiales que motivaron el dictado del Decreto referenciado, debiéndose adecuar el monto de las remuneraciones que se abonan en esta Municipalidad.\nQue se torna necesario realizar las adecuaciones correspondientes a la normativa vigente y registrar tales modificaciones al Presupuesto de Gastos - Ejercicio 2026.\nQue resulta necesario contar con la conformidad del Honorable Concejo Deliberante, para efectivizar la aplicación del Decreto dictado por el Departamento Ejecutivo\nPor ello, el Honorable Concejo Deliberante, en uso de sus atribuciones, sanciona la siguiente:\nORDENANZA\nArtículo 1º: Prestar conformidad a lo actuado por el Departamento Ejecutivo en el expediente Nº 4101-26.920-0 -2026, aprobar y convalidar en todos sus términos el Decreto Nro. 1434/2026 dictado por el Departamento Ejecutivo con fecha 11 de septiembre del año en curso- ad- referéndum de este Honorable Concejo Deliberante , que contempla lo siguiente:\n1) Otorgar un incremento salarial del siete por ciento (7%) acumulativo al salario básico del mes de agosto de 2026, pagadero con los haberes del mes de septiembre de 2026, en los sueldos básicos vigentes de los agentes que revisten desde la categoría 2 a\ncategoría 24 inclusive respecto de lo autorizado presupuestariamente para el ejercicio 2026, modificase el detalle de categorías, módulos y clases -anexo IV- establecido por el Artículo Nº 1 del Decreto Nº 1131/2026 aprobado y prestado conformidad por la Ordenanza Nº 2821/2026 (Decreto Nº 1297/2026) modificatorio del Artículo Nº 4 de la Ordenanza N° 2783/2025 (Decreto 1899/25) y establézcase el nuevo anexo que forma parte integrante del presente acto administrativo.\n2) Adecúense las remuneraciones establecidas por el Artículo Nº 2 del Decreto Nº 1131/2026, aprobado y prestado conformidad por la Ordenanza Nº 2821/2026 (Decreto Nº 1297/2026) modificatorio de los Artículos 6º, 7º y 10º de la Ordenanza Nro. 2783/25 (promulgada por Decreto 1899/25) en función del artículo precedentemente mencionado.\nArtículo 2º: De forma.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 24 de Septiembre de 2026.-", "archivo": "2026-Ord02836 (Incremento Salarial ).docx", "rz": "I", "c": "Personal municipal y del Cuerpo", "v": "Vigente (sujeta a verificación)", "fe": "24 de septiembre de 2026", "se": "Sesión Ordinaria", "vi": "El Decreto Nº 1434/2026 dictado por el Departamento Ejecutivo con fecha 11 de septiembre del año en curso- ad-referéndum de su convalidación por parte del Honorable Concejo Deliberante; y", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 16/10/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [["Ord", 2783, "Modifica", 1], ["Ord", 2821, "Refiere a", 1]], "pr": {"estado": "tacita_presunta", "limite": "2026-10-16", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-09-24", "ts": 1, "src": "docx"}, {"id": "ord-2835-2026", "t": "ord", "n": 2835, "y": 2026, "a": "Acciones de prevención del suicidio Banco Amarillo", "texto": "ORDENANZA N° 2835\nVISTO\nLa Resolución N. º 4/25 del Honorable Concejo Deliberante de San Andrés de Giles; la Ley Nacional N º 27.130 de Prevención del Suicidio y su Decreto Reglamentario N° 603/2021; la Ley Nacional N º 26.657 de Salud Mental; el Decreto-Ley Nº 6769/58 – Ley Orgánica de las Municipalidades de la Provincia de Buenos Aires; y la proximidad del 10 de septiembre, Día Mundial para la Prevención del Suicidio;\nCONSIDERANDO\nQue el suicidio constituye una problemática de salud pública que requiere políticas de prevención, sensibilización, escucha y acompañamiento, desarrolladas desde una perspectiva comunitaria e intersectorial;\nQue la Ley Nacional Nº 27.130 promueve acciones de prevención, asistencia y posvención, así como estrategias de sensibilización y fortalecimiento de redes de apoyo;\nQue este Honorable Concejo Deliberante ya se ha expresado sobre esta temática mediante la Resolución N° 4/25, en la que se manifestó la necesidad de fortalecer los Programas Municipales de Prevención al Suicidio y Asistencia a la persona con ideación y tentativa de suicidio, así como el trabajo intersectorial;\nQue dicha resolución constituye un antecedente institucional que debe ser reconocido y valorado como parte del camino que el Municipio y la comunidad vienen desarrollando en materia de prevención, sin que ello implique reiterar ni sustituir las acciones y dispositivos existentes;\nQue, en ese marco, resulta oportuno sumar una acción concreta, visible y comunitaria que contribuya a sensibilizar, promover la conversación y acercar a la comunidad información confiable sobre la importancia de pedir ayuda;\nQue la instalación de un “Banco Amarillo” en un espacio público del Partido de San Andrés de Giles puede constituirse en un símbolo comunitario de cuidado, escucha y prevención, favoreciendo la visibilización de la problemática sin estigmatizar a las personas que atraviesan situaciones de sufrimiento;\nQue esta iniciativa busca acompañar las acciones que ya se desarrollan y generar una herramienta sencilla de sensibilización, especialmente en el marco de Septiembre Amarillo y del 10 de septiembre, Día Mundial para la Prevención del Suicidio;\nQue el Banco Amarillo puede incorporar información institucional actualizada y un código QR que facilite el acceso a recursos oficiales, dispositivos de asistencia y orientación, procurando que la información sea clara, responsable y accesible;\nQue las acciones de prevención requieren continuidad durante todo el año, siendo septiembre una oportunidad para reforzar la sensibilización y el compromiso comunitario con el cuidado y la búsqueda temprana de ayuda;\nPor ello, el Honorable Concejo Deliberante de San Andrés de Giles sanciona la siguiente:\nORDENANZA\nARTÍCULO 1°: Disponer la instalación de un “Banco Amarillo” en un espacio público estratégico del Partido de San Andrés de Giles, como acción comunitaria de sensibilización y prevención en el marco de Septiembre Amarillo y del Día Mundial para la Prevención del Suicidio.\nARTÍCULO 2°: Deberá el Banco Amarillo estar acompañado por una placa, cartel o recurso de comunicación institucional que promueva la escucha, el cuidado y la búsqueda de ayuda, incorporando información actualizada sobre los dispositivos y canales oficiales de asistencia disponibles en el ámbito local y/o provincial.\nARTÍCULO 3°: Incorporar un código QR que permita acceder a información oficial, recursos de orientación y dispositivos de asistencia vinculados con la prevención del suicidio y la promoción de la salud mental.\nARTÍCULO 4°: La instalación del Banco Amarillo se realizarse durante el mes de septiembre, en torno al 10 del mismo, como parte de las acciones de sensibilización que se desarrollen en el marco de Septiembre Amarillo.\nARTÍCULO 5°: Invitar a las instituciones educativas, sanitarias, deportivas, sociales, culturales y comunitarias del Partido a acompañar las acciones de sensibilización que se desarrollen en torno al Banco Amarillo y a Septiembre Amarillo.\nARTÍCULO 6°: Comuníquese al Departamento Ejecutivo Municipal para su conocimiento y consideración, a través de las áreas que correspondan.\nARTÍCULO 7°: De forma.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 24 de Septiembre de 2026.-", "archivo": "2026-Ord02835 (Acciones de prevención del suicidio Banco Amarillo ).docx", "rz": "VII", "c": "Salud pública y hospital municipal", "v": "Vigente (sujeta a verificación)", "fe": "24 de septiembre de 2026", "se": "Sesión Ordinaria", "vi": "La Resolución N. º 4/25 del Honorable Concejo Deliberante de San Andrés de Giles; la Ley Nacional N º 27.130 de Prevención del Suicidio y su Decreto Reglamentario N° 603/2021; la Ley Nacional N º 26.657 de Salud Mental; el Decreto-Ley Nº 6769/58 – Ley Orgánica de las Municipalidades de la Provincia de Buenos Aires; y la proximidad del 10 de septiembre, Día Mundial para la Prevención del Suicidio;", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 16/10/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [], "pr": {"estado": "tacita_presunta", "limite": "2026-10-16", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-09-24", "ts": 1, "src": "docx"}, {"id": "ord-2834-2026", "t": "ord", "n": 2834, "y": 2026, "a": "Imposición del nombre Los Molinos a una calle de Villa Ruiz", "texto": "ORDENANZA N° 2834\nVISTO:\nLa solicitud presentada por vecinos de la Localidad de Villa Ruíz referida a imponer el nombre de “Los Molinos” a una calle en la mencionada localidad;\nCONSIDERANDO:\nQue a través de la imposición de nombres a calles y barrios se contribuye a su reconocimiento, fortaleciendo la identidad local y constituyendo además una herramienta útil para la identificación geográfica, la prestación de servicios públicos y la organización administrativa;\nQue la ley orgánica de las municipalidades le confiere al Honorable Concejo Deliberante en su artículo 27 inciso 4) la facultad de “la imposición de nombres a las calles y los sitios públicos”;\nQue debe tenerse en cuenta que las denominaciones comúnmente surgen de nombres y valores universales y nacionales, por lo que con el fin de consolidar identidad y pertenencia será favorable enriquecerlas con aquellos que pertenezcan a la propia comunidad geográfica y humana y resulten propicios para construir memoria, visibilizar y valorar lo cercano;\nQue este Honorable Concejo Deliberante tiene entre sus funciones preservar la memoria colectiva de la ciudad, promoviendo acciones que valoricen la cultura e historia de San Andrés de Giles;\nQue el nombre “Los Molinos” surge como idea de los vecinos y vecinas que habitan esa calle, con una sólida base de consenso, considerándola representativa y adecuada para esta nueva arteria;\nQue tener designación oficial de nombre para la calle, facilita la identificación de los domicilios, atributo de las personas según el Código Civil, también contribuye al ordenamiento urbano y permite optimizar servicios como mercado envíos y correspondencia postal;\nPor ello, en uso de las atribuciones que le son propias el Honorable Concejo Deliberante de San Andrés de Giles sanciona la siguiente:\nORDENANZA\nArtículo 1°: Establecer la denominación de “Los Molinos” a la calle ubicada entre calles Sarmiento y Santa María de la localidad de Villa Ruíz.\nArtículo 2°: Solicítese al Departamento Ejecutivo que arbitre los medios necesarios para la demarcación y señalización de la calle mencionada en el artículo 1°.\nArtículo 3°: De forma.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 24 de Septiembre de 2026.-", "archivo": "2026-Ord02834 (Imposición del nombre Los Molinos a una calle de Villa Ruiz ).docx", "rz": "XI", "c": "Imposición de nombres a calles y caminos", "v": "Vigente (sujeta a verificación)", "fe": "24 de septiembre de 2026", "se": "Sesión Ordinaria", "vi": "La solicitud presentada por vecinos de la Localidad de Villa Ruíz referida a imponer el nombre de “Los Molinos” a una calle en la mencionada localidad;", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 16/10/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [], "pr": {"estado": "tacita_presunta", "limite": "2026-10-16", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-09-24", "ts": 1, "src": "docx"}, {"id": "ord-2833-2026", "t": "ord", "n": 2833, "y": 2026, "a": "Imposición de nombre La Estancia a un barrio", "texto": "ORDENANZA N° 2833\nVISTO:\nLa solicitud presentada por vecinos de la zona, referida a reconocer como Barrio “La Estancia” al sector comprendido entre la calle 110 y el Camino Provincial 094-01; y\nCONSIDERANDO:\nQue a través de la imposición de un nombre se logra identificar un barrio, lo mismo sucede con sus calles, fortaleciendo la identidad local, otorgando sentido de pertenencia y arraigo a las actuales y futuras generaciones y constituye además una herramienta útil para la identificación geográfica, la prestación de servicios públicos y la organización administrativa;\nQue el nombre propuesto rescata la historia y el carácter del lugar, consolidando un sentido de pertenencia compartido. “La Estancia” se trata de una denominación ya reconocida y utilizada cotidianamente por las familias que allí viven;\nQue la denominación oficial permitirá una correcta individualización del área en los planos y registros municipales, facilitando trámites administrativos, catastrales y de planificación territorial;\nQue contar con una designación formal resulta indispensable para agilizar el acceso a servicios públicos y emergencias, policía, bomberos y ambulancia, así como para optimizar el tendido de servicios esenciales, mercado envíos y correspondencia postal;\nQue este Honorable Concejo Deliberante tiene entre sus funciones preservar la memoria colectiva de la ciudad, promoviendo acciones que valoricen la cultura e historia de San Andrés de Giles;\nPor ello, en uso de las atribuciones que le son propias el Honorable Concejo Deliberante de San Andrés de Giles sanciona la siguiente:\nORDENANZA\nArtículo 1°: Reconocerse oficialmente como Barrio “La Estancia” al sector de la ciudad comprendido entre la calle 110 y el Camino Provincial 094-01.-\nArtículo 2°: De forma.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 24 de Septiembre de 2026.-", "archivo": "2026-Ord02833 (Imposición de nombre La Estancia a un barrio ).docx", "rz": "XI", "c": "Imposición de nombres a calles y caminos", "v": "Vigente (sujeta a verificación)", "fe": "24 de septiembre de 2026", "se": "Sesión Ordinaria", "vi": "La solicitud presentada por vecinos de la zona, referida a reconocer como Barrio “La Estancia” al sector comprendido entre la calle 110 y el Camino Provincial 094-01; y", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 16/10/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [], "pr": {"estado": "tacita_presunta", "limite": "2026-10-16", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-09-24", "ts": 1, "src": "docx"}, {"id": "ord-2832-2026", "t": "ord", "n": 2832, "y": 2026, "a": "Homologación Adenda con Papelera San Andrés", "texto": "ORDENANZA N° 2832\nVISTO:\nEl expediente N° 4101-20474-0-2024, iniciado a raíz de un convenio celebrado entre el Municipio y la firma Papelera San Andrés de Giles, y\nCONSIDERANDO:\nQue, a través de la Ordenanza Nº 2755/25, sancionada en fecha 29.05.2025, promulgada mediante Decreto Nº 1158 de fecha 02 de junio del 2025, se homologó el convenio suscripto oportunamente entre el Municipio y el Sr. Máximo Víctor Gino Gagliardi, en representación de la firma PAPELERA SAN ANDRES DE GILES SOCIEDAD ANONIMA, cuyo objeto era la construcción por parte de la empresa de un depósito de materia prima – no industrial- en un terreno lindero al que se encuentra instalado el emprendimiento.\nQue con fecha 18.06.26, la empresa antes referenciada, realiza una presentación ante el Departamento Ejecutivo, a través de la cuál pone en conocimiento de ésta que ha adquirido una fracción de terreno lindera a la Parcela 118-cg, motivo por lo cual solicita la ampliación del depósito de materia prima no industrial oportunamente autorizado, en 1.925 m2 más, a construirse en las parcelas 118-ch y 118-cg.\nQue motiva la petición del requirente, la necesidad de completar el proyecto de inversión informado y que es de vital importancia para la actividad, ya que amplía la capacidad de almacenamiento y logística de la firma.\nQue, la empresa sumaría como compensación a lo solicitado, el aporte de una máquina excavadora marca Taurus modelo HT-17 Estándar, con el objeto de facilitar las tareas de limpieza llevadas a cabo por el Municipio.\nQue, debido a la circunstancia narrada, las partes acordaron realizar una ampliación al convenio referenciado, mediante la suscripción de una adenda.\nQue al respecto se expidió la Sra. Directora de Planeamiento y Obras Particulares, la Sra. Directora de Producción, el Sr. Director de Ambiente.\nQue, también emite opinión en igual sentido la Asesoría Letrada Municipal, no formulando objeciones al respecto.\nQue, en consecuencia, deberá homologarse por parte de este Órgano Deliberativo, la adenda suscripta por el Municipio y la firma PAPELERA SAN ANDRES DE GILES SOCIEDAD ANONIMA.\nPor ello, el HCD en uso de las atribuciones que le son propias, sanciona la siguiente:\nORDENANZA\nARTICULO 1º: Homologar la adenda suscripta con fecha 07 de septiembre del año en curso, entre el Sr. Intendente Municipal y el Sr. Máximo Víctor Gino Gagliardi, en representación de la firma PAPELERA SAN ANDRES DE GILES SOCIEDAD ANONIMA, que como Anexo I forma parte integrante de la presente ordenanza.\nARTICULO 2º: Ratificar la homologación del convenio autorizado por ordenanza Nº 2755/25, con el agregado de la adenda que como anexo I forma parte integrante del presente acto administrativo.\nARTICULO 3º: Aceptar la donación ofrecida por la empresa a la municipalidad, de una máquina excavadora marca Taurus modelo HT-17 Estándar, en virtud de lo establecido en el artículo nº 57 de la LOM, destinada a facilitar las tareas de limpieza llevadas a cabo por el Municipio.\nARTICULO 4º: Registrar. Comunicar a las áreas pertinentes en virtud de la naturaleza de la presente norma, publicar y archivar.\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 10 de Septiembre de 2026.-", "archivo": "2026-Ord02832 (Homologación Adenda con Papelera San Andrés).docx", "rz": "III", "c": "Planeamiento urbano y zonificación", "v": "Vigente (sujeta a verificación)", "fe": "10 de septiembre de 2026", "se": "Sesión Ordinaria", "vi": "El expediente N° 4101-20474-0-2024, iniciado a raíz de un convenio celebrado entre el Municipio y la firma Papelera San Andrés de Giles, y", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 01/10/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [["Ord", 2755, "Modifica", 1]], "pr": {"estado": "tacita_presunta", "limite": "2026-10-01", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-09-10", "ts": 1, "src": "docx"}, {"id": "ord-2831-2026", "t": "ord", "n": 2831, "y": 2026, "a": "Plan Director de Arbolado", "texto": "ORDENANZA N° 2831\nVisto:\nLa necesidad de dar continuidad al proceso de planificación técnica y operativa para ordenar, fortalecer y proyectar a largo plazo el arbolado urbano, en el marco de las disposiciones de la Ley Provincial N°12.276/1999 y la Ordenanza Municipal N°1635/2012 y en articulación con los objetivos ambientales, sociales y territoriales del municipio, y;\nConsiderando:\nQue el arbolado público urbano constituye un componente esencial de la infraestructura verde de las ciudades, entendido no sólo como un elemento paisajístico o decorativo, sino como un sistema vivo que presta múltiples servicios ecosistémicos;\nQue dicha infraestructura verde desempeña un rol clave al capturar carbono, reducir la isla de calor urbana, mejorar la calidad del aire y moderar el consumo energético por regulación térmica;\nQue, en un contexto global de cambio climático, el diseño y la gestión estratégica del arbolado adquieren un papel central en las políticas locales de sostenibilidad;\nQue es primordial establecer una clasificación de especies arbóreas por magnitud y segmentar su uso urbano en función del tendido aéreo o el ancho de veredas, teniendo en cuenta además la necesidad de priorizar especies nativas o adaptadas, de crecimiento controlado y baja exigencia de mantenimiento:\nPor ello el HCD, en uso de atribuciones que le son propias, sanciona la siguiente:\nORDENANZA\nArtículo 1°: Apruébese el Plan Director de Arbolado Urbano del Partido de San Andrés de Giles, que como Anexo forma parte integrante de la presente, según el siguiente detalle:\n1. INTRODUCCIÓN:\n1.1 Resumen\n1.2 Antecedentes\n1.3 Aportes y límites del Plan Regulador 2022\n1.4 Diagnóstico del estado actual del arbolado público\n2. CARACTERIZACIÓN:\n2.1 Componentes edáficos, climatológicos y de relieve\n2.2 Componente poblacional\n2.3 Componente urbanístico\n2.4. Componentes forestales\n2.5 Componente Orgánico\n3. OBJETIVOS:\n3.1 Objetivos específicos\n3.2 Metas\n4. LINEAMIENTOS TÉCNICOS:\n4.1. Criterios generales\n4.2. Clasificación por magnitud\n4.3. Selección de especies\n5. METODOLOGÍA Y ACTIVIDADES:\n5.1 Organización anual de tareas según condiciones climáticas\n5.2 Organización del personal\n5.3 Esquema de trabajo por tarea\n5.4 Flexibilidad y adaptabilidad\n6. PARTICIPACIÓN CIUDADANA.\nAnexo 1\nAnexo 2 -----------------------------------------------------------------------------------------------\nArtículo 2º: Autorizase al Departamento Ejecutivo a realizar las adecuaciones presupuestarias correspondientes a efectos de cumplimentar los fines de la presente Ordenanza. -------------------------------------------------------------------------------------------\nArtículo 3º: Abróganse las Ordenanzas Municipales Nº34/1981 y N°38/1990 y toda otra disposición local que se oponga a la presente. ---------------------------------------------\nArtículo 4º: Previa promulgación de la presente, comuníquese a la Dirección de Bosques y Forestación (ex Dirección de Desarrollo Forestal) dependiente del Ministerio de Desarrollo Agrario del Gobierno de la Provincia de Buenos Aires. ----------------------\nArtículo 5°: De forma. -----------------------------------------------------------------------------\nDada en Sesión Ordinaria celebrada por este Concejo Deliberante, en San Andrés de Giles, el día 10 de Septiembre de 2026.-", "archivo": "2026-Ord02831 (Plan Director de Arbolado).docx", "rz": "V", "c": "Arbolado público, espacios verdes y biodiversidad", "v": "Vigente (sujeta a verificación)", "fe": "10 de septiembre de 2026", "se": "Sesión Ordinaria", "vi": "La necesidad de dar continuidad al proceso de planificación técnica y operativa para ordenar, fortalecer y proyectar a largo plazo el arbolado urbano, en el marco de las disposiciones de la Ley Provincial N°12.276/1999 y la Ordenanza Municipal N°1635/2012 y en articulación con los objetivos ambientales, sociales y territoriales del municipio, y;", "au": "Int. Sr. Miguel Ángel Gesualdi", "nt": "No se publicó en el Boletín Oficial Municipal un decreto de promulgación ni de veto. Vencido el plazo de diez días hábiles del art. 108 inc. 2 de la Ley Orgánica de las Municipalidades (estimado al 01/10/2026), la ordenanza se presume promulgada de hecho. Sujeto a verificación.", "rf": [["Ord", 34, "Deroga", 0], ["Ord", 38, "Deroga", 1], ["Ord", 1635, "Refiere a", 1]], "pr": {"estado": "tacita_presunta", "limite": "2026-10-01", "etiqueta": "Promulgada de hecho (presunta)"}, "fs": "2026-09-10", "ts": 1, "src": "docx"}, {"id": "res-24-2021", "t": "res", "n": 24, "y": 2021, "a": "Autorizase al D.E. para que realice la demarcación y señalización de espacios reservados para el estacionamiento de motos y ciclomotores establecidos en la ciudad de San Andrés de Giles que se detallan en el artículo 2° de la presente norma", "texto": "San Martin 888 1° piso – Tel 02325 442662 – hcdsadegiles@hotmail.com\n“Año de la Salud y del Personal Sanitario” “Año del Bicentenario del fallecimiento del General Miguel de Güemes\nSan Andrés de Giles, el día 22 de abril de 2021\nORDENANZA N° 24/21\nVisto:\nLa necesidad de lograr un ordenamiento en la ubicación, estacionamiento de motos y motocicletas en la ciudad de San Andrés de Giles teniendo en cuenta que este tipo de vehículos no solo ha crecido considerablemente , sino también que se ha convertido en una herramienta de trabajo; y\nConsiderando:\nQue el número de vecinos de nuestra ciudad que se trasladan en motos y ciclomotores aumenta en forma exponencial;\nQue no se cuenta con espacios suficientes reservados para el estacionamiento de los vehículos mencionados que ofrezcan seguridad a quienes las conducen y a quienes se desplazan en la vía pública;\nQue resulta necesario demarcar un espacio reservado al estacionamiento de motos y ciclomotores en las inmediaciones del Hospital Municipal San Andrés;\nQue a propuesta de este HCD el Departamento Ejecutivo arbitrará los medios para localizar el estacionamiento de motos y ciclomotores s obre lacalzada, en forma contigua a la de los automóviles con el fin de ordenar el estacionamiento vehicular en general y a la vez jerarquizar los espacios destinados a la circulación de peatones;\nPor ello el HCD en uso de sus atribuciones sanciona la siguiente.\nORDENANZA\nArtículo 1°: Autorizase al D.E. para que realice la demarcación y señalización de espacios reservados para el estacionamiento de motos y ciclomotores establecidos en la ciudad de San Andrés de Giles que se detallan en el artículo 2° de la presente norma.\nArtículo 2°: Se establece como lugares reservados para el estacionamiento los siguientes:\nSan Martin 888 1° piso – Tel 02325 442662 – hcdsadegiles@hotmail.com\n“Año de la Salud y del Personal Sanitario” “Año del Bicentenario del fallecimiento del General Miguel de Güemes\na) Calle Rivadavia en intersección con calle Urquiza sobre numeración par desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Rawson.\nb) Calle Rivadavia en intersección con calle Quintana sobre numeración par desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Urquiza.\nc) Calle Rivadavia en intersección con calle Carlos Pellegrini sobre numeración par desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Quintana.\nd) Calle Rivadavia en intersección con la calle Alsina sobre numeración par desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Carlos Pellegrini.\ne) Calle Rivadavia en intersección con la calle Avellaneda sobre numeración par desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Carlos Pellegrini .f) Calle Rivadavia en intersección con la calle Belgrano sobre numeración par desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Mitre.\ng) Calle Rivadavia en intersección con la calle Saavedra sobre numeración par desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Sarmiento.\nh) Calle Rivadavia en intersección con la calle Hidalgo sobre numeración par desde la líne a habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Saavedra.\ni) Calle Hidalgo en intersección con la calle 25 de Mayo sobre numeración impar desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección a calle Maipú (supermercado Romeo) .\nj) Calle Moreno entre las calles 25 de Mayo y Rivadavia sobre numeración par a Mitad de cuadra finalizando Jardín de Infantes Ntra. Señora de Luján cinco metros de largo por dos metros de ancho en dirección hacia calle Rivadavia.\nk) Calle Belgrano en intersección con calle 25 de Mayo sobre numeración impar desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Rivadavia.\nSan Martin 888 1° piso – Tel 02325 442662 – hcdsadegiles@hotmail.com\n“Año de la Salud y del Personal Sanitario” “Año del Bicentenario del fallecimiento del General Miguel de Güemes\nl) Calle Mitre en intersección con calle 25 de Mayo sobre numeración par desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Maipú.\nm) En calle 25 de Mayo en intersección con la calle Avellaneda sobre numeración impar desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Mitre n) En calle 25 de Mayo en intersección con la calle Alsina sobre numeración impar desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Avellaneda.\no) En calle 25 de Mayo en intersección con la calle Carlos Pellegrini so bre numeración impar desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho hacia calle Alsina.\np) Calle Belgrano en intersección con la calle San Martín sobre numeración par desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle 9 de Julio.\nq) Calle Quintana entre las calle Rivadavia y San Martín sobre numeración par a mitad de cuadra cinco metros de largo por dos metros de ancho.\nr) Calle Alsina en intersección con la calle 9 de Julio sobre numeración impar desde la línea habilitante de estacionamiento cinco metros de largo por dos metros de ancho en dirección hacia calle Bernardo de Irigoyen. (Anses).\ns) Calle Rivadavia entre las calles Moreno y Sarmiento y Sarmiento sobre numeración par desde donde finalizada la línea demarcatoria de prohibido estacionar de la intersección de las calles Rivadavia y Moreno.\nt) Av. Malvinas Argentinas sobre numeración par desde la línea habilitante de estacionamiento, cinco metros de largo por dos metros de ancho hacia calle Colonos Irlandeses.\nu) Av. Malvinas Argentinas sobre numeración impar desde la línea habilitante de estacionamiento, cinco metros de largo por dos metros de ancho hacia calle Colonos Irlandeses.\nArtículo 3°: El Departamento Ejecutivo realizará un corralito en los sectores mencionados, conjuntamente con la siguiente leyenda:\n”Estacionamiento exclusivo y obligatorio , motos y ciclomotores Ord Nº “ sobre los espacios destinados en todo el trayecto de la calle Rivadavia. “Estacionamiento exclusivo motos y ciclomotores. Ord. Nº, en el resto de los espacios cedidos.\nSan Martin 888 1° piso – Tel 02325 442662 – hcdsadegiles@hotmail.com\n“Año de la Salud y del Personal Sanitario” “Año del Bicentenario del fallecimiento del General Miguel de Güemes\nArtículo 4°: Procédase a la señalización, demarcación y delimitación correspondiente colocando la señalética, deberá además estar pintando el cordón y en la calzada la marcación a 45º en el sentido de circulación para su estacionamiento.\nArtículo 5°: Autorízase al D.E. a efectuar un corrimiento de un metro de ancho por diez metros de largo en la acera del Hospital Municipal San Andrés con el fin de establecer un espacio destinado al estacionamiento de motos y ciclomotores.\nArtículo 6°: Autorizase al Departamento Ejecutivo a efectuar las adecuaciones presupuestarias correspondientes para dar cumplimiento a lo normado.\nArtículo 7°: De forma.\nDada en Sesión Ordinaria celebrada por este Honorable Concejo Deliberante de San Andrés de Giles, el día 22 de abril de 2021.-", "archivo": "2021-Res-24-21-Estacionamiento-de-motos-y-ciclomotores..pdf", "rz": "VIII", "c": "Tránsito, seguridad vial y estacionamiento", "v": "Vigente (sujeta a verificación)", "fe": "22 de abril de 2021", "se": "Sesión Ordinaria", "vi": "La necesidad de lograr un ordenamiento en la ubicación, estacionamiento de motos y motocicletas en la ciudad de San Andrés de Giles teniendo en cuenta que este tipo de vehículos no solo ha crecido considerablemente , sino también que se ha convertido en una herramienta de trabajo; y", "au": "Int. Cr. Carlos Javier Puglelli", "nt": "Autor: Bloque Interbloque Juntos por el Cambio. Ingresado el 14/10/2021. Fuente: Sitio del H.C.D. (https://hcdsanandresdegiles.com.ar/2021-res-24-21-estacionamiento-de-motos-y-ciclomotores/).", "rf": [], "pr": {"estado": "hcd", "etiqueta": "Aprobada por el H.C.D."}, "fs": "2021-04-22", "ts": 1, "src": "hcd"}, {"id": "com-3-2021", "t": "com", "n": 3, "y": 2021, "a": "Solicitar al Departamento Ejecutivo promueva la poda responsable realizando una amplia campaña de difusión en los distintos medios de comunicación locales, teniendo como objetivo la concientización y sensibilización en pos del cuidado del a", "texto": "San Martin 888 1° piso – Tel 02325 442662 – hcdsadegiles@hotmail.com\n“Año de la Salud y del Personal Sanitario” “Año del Bicentenario del fallecimiento del General Miguel de Güemes”\nSan Andrés de Giles, 22 de abril de 2021.\nCOMUNICACIÓN N° 3/21\nVisto:\nLa necesidad de articular y profundizar acciones en torno del cuidado del arbolado público del Partido de San Andrés de Giles como recurso indispensable que contribuye a la calidad del ambiente, y\nConsiderando:\nQue es necesario generar en la población la cultura del árbol, valorando sus beneficios sobre la calidad de vida.\nQue conforme fuera establecido en la Ordenanza N°1635, es esencial reconocer en el arbolado público un patrimonio natural y cultural.\nQue el Área de Medio Ambiente, viene trabajando en la reposición de especies y forestación de espacios públicos.\nQue muchos vecinos muestran una actitud responsable en el cuidado del arbolado realizando las tareas de preservación con podas imprescindibles y cuidadosas.\nQue también se puede observar en las calles de nuestra ciudad la necesidad de realizar poda de los árboles con la finalidad de conservación y el buen desarrollo de los ejemplares.\nQue en años anteriores se ha podido observar mutilaciones en las copas de los árboles que en lugar de ser acciones de preservación y cuidado se transforman en dañosas y destructivas.\nQue es necesario reactivar el Registro Permanente de Forestadores, Podadores y Control de plagas vegetales de San Andrés de Giles creado por Ordenanza 1635. Lo que permitirá el control de la poda, desgaje y extracción de árboles de la vía pública con el objetivo de proteger e incrementar el arbolado urbano existente.\nQue la capacitación y formación a las personas que trabajan como podadores o jardineros es una herramienta nodal para el cuidado de nuestro patrimonio forestal, como así también se transforme en un instrumento de oportunidad laboral.\nQue si el ambiente es responsabilidad de todos, le cabe al Municipio el diseño y la implementación de políticas públicas que ordenen, que controlen y que protejan el entorno que es, ni más ni menos que nuestro hogar y en el cumplen una función esencial los árboles y de ahí l importancia de su cuidado.\nSan Martin 888 1° piso – Tel 02325 442662 – hcdsadegiles@hotmail.com\n“Año de la Salud y del Personal Sanitario” “Año del Bicentenario del fallecimiento del General Miguel de Güemes”\nPor ello, el Honorable Concejo Deliberante en uso de las atribuciones que le son propias sanciona la siguiente:\nCOMUNICACIÓN\nArtículo 1°: Solicitar al Departamento Ejecutivo promueva la poda responsable realizando una amplia campaña de difusión en los distintos medios de comunicación locales, teniendo como objetivo la concientización y sensibilización en pos del cuidado del arbolado público.\nArtículo 2°: Instar a la apertura del Registro Permanente de Forestadores, Podadores y Control de Plagas vegetales de San Andrés de Giles, en el que deberán obligatoriamente inscribirse las personas físicas o jurídicas que se dediquen a dichas tareas en relación al arbolado urbano.\nArtículo 3°: Solicitar la realización de cursos de capacitación como herramienta de protección del arbolado urbano, fortaleciendo la conciencia ambiental y generar mayores oportunidades laborales a quienes trabajen como podadores y jardineros.\nArtículo 4°: De forma.\nDada en Sesión Ordinaria celebrada por este Honorable Concejo Deliberante de San Andrés de Giles, el día 22 de abril de 2021.-", "archivo": "3-21-Promocion-poda-responsable-ano-2021.pdf", "rz": "X", "c": "Pedidos de informes y requerimientos al D.E.", "v": "Cumplida / declarativa", "fe": "22 de abril de 2021", "se": "Sesión Ordinaria", "vi": "La necesidad de articular y profundizar acciones en torno del cuidado del arbolado público del Partido de San Andrés de Giles como recurso indispensable que contribuye a la calidad del ambiente, y", "au": "Int. Cr. Carlos Javier Puglelli", "nt": "Autor: Bloque Interbloque Juntos por el Cambio. Ingresado el 14/10/2021. Fuente: Sitio del H.C.D. (https://hcdsanandresdegiles.com.ar/2021-com-3-21-promocion-poda-responsable-ano-2021/).", "rf": [], "pr": {"estado": "hcd", "etiqueta": "Aprobada por el H.C.D."}, "fs": "2021-04-22", "ts": 1, "src": "hcd"}], "efectos": [{"id": "ord-38-1990", "t": "ord", "n": 38, "y": 1990, "ts": 1, "ri": [["Ord", 2831, "Deroga"]], "efecto": true, "v": "Derogada"}, {"id": "ord-1635-2012", "t": "ord", "n": 1635, "y": 2012, "ts": 1, "ri": [["Ord", 2831, "Refiere a"]], "efecto": true}, {"id": "ord-2755-2025", "t": "ord", "n": 2755, "y": 2025, "ts": 1, "ri": [["Ord", 2832, "Modifica"]], "efecto": true, "v": "Vigente con modificaciones"}, {"id": "ord-2783-2025", "t": "ord", "n": 2783, "y": 2025, "ts": 1, "ri": [["Ord", 2836, "Modifica"]], "efecto": true, "v": "Vigente con modificaciones"}, {"id": "ord-2821-2026", "t": "ord", "n": 2821, "y": 2026, "ts": 1, "ri": [["Ord", 2836, "Refiere a"]], "efecto": true}, {"id": "ord-2306-2020", "t": "ord", "n": 2306, "y": 2020, "ts": 1, "ri": [["Ord", 2838, "Deroga parcialmente"]], "efecto": true, "v": "Vigente con modificaciones"}, {"id": "ord-1770-2014", "t": "ord", "n": 1770, "y": 2014, "ts": 1, "ri": [["Ord", 2840, "Modifica"]], "efecto": true, "v": "Vigente con modificaciones"}, {"id": "ord-2617-2023", "t": "ord", "n": 2617, "y": 2023, "ts": 1, "ri": [["Ord", 2840, "Refiere a"]], "efecto": true}, {"id": "ord-2546-2022", "t": "ord", "n": 2546, "y": 2022, "ts": 1, "ri": [["Ord", 2842, "Modifica"]], "efecto": true, "v": "Vigente con modificaciones"}, {"id": "ord-1211-2007", "t": "ord", "n": 1211, "y": 2007, "ts": 1, "ri": [["Ord", 2844, "Refiere a"]], "efecto": true}, {"id": "ord-2452-2021", "t": "ord", "n": 2452, "y": 2021, "ts": 1, "ri": [["Ord", 2845, "Modifica"]], "efecto": true, "v": "Vigente con modificaciones"}]};
